}
.screen-end.is-loss .verdict h2{color:#ddd2bd}
.verdict p{
  margin-top:10px;max-width:30ch;font-family:var(--type);font-size:clamp(9.5px,1.3vh,11px);
  line-height:1.55;color:var(--paper-dim);
}
.end-card{
  flex-shrink:0;margin-bottom:10px;padding:10px 12px;border:1px solid rgba(233,221,196,.14);
  background:linear-gradient(180deg,rgba(24,19,14,.8),rgba(9,7,5,.92));
  box-shadow:0 16px 40px rgba(0,0,0,.5);backdrop-filter:blur(4px);
}
.end-row{display:flex;align-items:baseline;gap:10px;padding:4px 0;border-bottom:1px solid rgba(233,221,196,.07);line-height:1.2}
.end-row:last-of-type{border-bottom:0}
.end-row span{flex:0 0 68px;font-size:6px;letter-spacing:.19em;color:var(--paper-faint);text-transform:uppercase}
.end-row b{font-family:var(--serif);font-size:clamp(11px,1.55vh,13px);font-weight:900;color:var(--paper);line-height:1.15}
.screen-end.is-win #endKiller{color:var(--gold-bright)}
.screen-end.is-loss #endKiller{color:#c2a08d}
.end-nail{
  margin-top:7px;padding-top:7px;border-top:1px solid rgba(233,221,196,.12);
  font-family:var(--type);font-size:clamp(7.5px,1.02vh,8.8px);line-height:1.45;color:var(--paper-faint);
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;
}
.end-nail b{color:var(--gold);font-weight:400}

/* ================= CONFIRM OVERLAY ================= */
.overlay{
  position:absolute;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;padding:24px;
  background:rgba(4,3,2,.78);backdrop-filter:blur(7px);
  opacity:0;visibility:hidden;pointer-events:none;transition:opacity .25s,visibility .25s;
}
.overlay.open{opacity:1;visibility:visible;pointer-events:auto}
.confirm-card{
  width:100%;max-width:330px;padding:20px 18px 16px;text-align:center;
