  .clue-sheet{padding:9px 11px 8px;margin-top:8px}
  .clue-text{font-size:10.5px;line-height:1.42;min-height:0}
  .footer-actions .btn{min-height:44px}
  .accuse-head{margin-top:9px;margin-bottom:7px}
  .accuse-head p{font-size:8.5px;margin-top:5px}
  .accuse-row{padding:5px 7px}
