.notes-grid div{min-width:0}
.notes-grid span{display:block;font-size:5.4px;letter-spacing:.15em;color:#806643;text-transform:uppercase;line-height:1}
.notes-grid b{display:block;margin-top:2px;font-family:var(--type);font-size:7px;font-weight:400;line-height:1.25;color:#2a2015;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
