.accuse-case b{display:block;margin-top:3px;font-family:var(--type);font-size:8px;font-weight:400;line-height:1.2;color:var(--paper-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.accuse-list{flex:1;min-height:0;display:flex;flex-direction:column;justify-content:space-evenly;gap:8px;padding:4px 0}
.accuse-row{
  display:flex;align-items:center;gap:10px;width:100%;padding:8px 9px;text-align:left;

