const { chromium } = require('playwright');
const assert = require('assert');

async function fit(page, label) {
  const bad = await page.evaluate(() => {
    const active = document.querySelector('.screen.is-active');
    const r = active.getBoundingClientRect();
    const out = [];
    for (const el of active.querySelectorAll('button, h1, h2, h3, p, .call-card, .clue-sheet, .board-body, .end-card, .verdict-figure')) {
      if (!el.offsetParent && getComputedStyle(el).position !== 'fixed') continue;
      const b = el.getBoundingClientRect();
      if (b.height > 0 && (b.bottom > innerHeight + 1 || b.top < -1)) out.push({ tag: el.tagName, cls: el.className, id: el.id, top: Math.round(b.top), bottom: Math.round(b.bottom) });
    }
    const scroll = [...active.querySelectorAll('*')].filter(e => e.scrollHeight > e.clientHeight + 2 && getComputedStyle(e).overflow === 'visible').length;
    return { screen: active.id, out, scroll, scrollH: active.scrollHeight, clientH: active.clientHeight };
  });
  if (bad.out.length || bad.scrollH > bad.clientH + 2) console.log('FIT', label, JSON.stringify(bad));
  else console.log('FIT OK', label, bad.screen);
}

(async () => {
  const browser = await chromium.launch();
  for (const [w,h] of [[390,844],[360,640],[430,932]]) {
    const page = await browser.newPage({ viewport:{width:w,height:h}, deviceScaleFactor:1 });
    const errors = [];
    page.on('pageerror', e => errors.push(String(e)));
    await page.goto('http://localhost:8080/index.html');
    await page.waitForTimeout(500);
    await fit(page,'office');

    // win path via clicks
    await page.click('#btnGoScene');
    await page.waitForTimeout(600);
    await fit(page,'scene');
    const cases = await page.evaluate(() => window.__midnight.state.caseData);
    for (const key of ['desk','window','coat','safe']) {
      await page.locator(`.hotspot[data-object="${key}"]`).click({ force:true });
      await page.waitForTimeout(420);
      await fit(page,`zoom-${key}`);
      if (w===390 && key==='desk') await page.screenshot({path:`/tmp/opencode/shots/v-zoom-${w}x${h}.png`});
      await page.click('#btnZoomOut');
      await page.waitForTimeout(300);
    }
    await page.click('.scene-foot [data-open-board]');
    await page.waitForTimeout(700);
    await fit(page,'board');
    if (w===390) await page.screenshot({path:`/tmp/opencode/shots/v-board-${w}x${h}.png`});
    await page.click('#btnAccuse');
    await page.waitForTimeout(500);
    await fit(page,'accuse');
    if (w===390) await page.screenshot({path:`/tmp/opencode/shots/v-accuse-${w}x${h}.png`});
    await page.click(`.accuse-row[data-index="${cases.killerIndex}"]`);
    await page.click('#btnMakeAccusation');
    await page.waitForTimeout(300);
    await page.click('#btnDoAccuse');
    await page.waitForTimeout(900);
    await fit(page,'end-win');
    const win = await page.evaluate(() => ({
      screen: window.__midnight.state.screen,
      active: document.querySelector('.screen.is-active')?.id,
      cls: document.querySelector('#screen-end').className,
      stamp: document.querySelector('#vfStamp').textContent,
      name: document.querySelector('#vfName').textContent,
      missing: document.querySelector('#verdictFigure').classList.contains('is-missing')
    }));
    console.log('WIN', w+'x'+h, JSON.stringify(win));
    assert.equal(win.active,'screen-end'); assert(win.cls.includes('is-win')); assert.equal(win.stamp,'ARRESTED'); assert(!win.missing);

    // loss: correct name, no gun
    await page.evaluate(() => { const m=window.__midnight; m.startCase(); });
    await page.evaluate(() => {
      const m=window.__midnight, c=m.state.caseData;
      const gun=Object.values(c.clues).find(x=>x.type==='gun');
      for (const k of Object.keys(c.clues)) if (k!==gun.object) m.state.found.add(k);
      m.showScreen('accuse');
    });
    await page.waitForTimeout(500);
    const gi = await page.evaluate(() => window.__midnight.state.caseData.killerIndex);
    await page.click(`.accuse-row[data-index="${gi}"]`);
    await page.click('#btnMakeAccusation');
    await page.waitForTimeout(250);
    await page.click('#btnDoAccuse');
    await page.waitForTimeout(900);
    const nogun = await page.evaluate(() => ({
      cls: document.querySelector('#screen-end').className,
      stamp: document.querySelector('#vfStamp').textContent,
      failure: window.__midnight.state.failure,
      missing: document.querySelector('#verdictFigure').classList.contains('is-missing')
    }));
    console.log('NOGUN', w+'x'+h, JSON.stringify(nogun));
    assert(nogun.cls.includes('is-loss')); assert.equal(nogun.stamp,'AT LARGE'); assert.equal(nogun.failure,'no-gun'); assert(nogun.missing);

    // loss: wrong name with gun
    await page.evaluate(() => { const m=window.__midnight; m.startCase(); });
    await page.evaluate(() => {
      const m=window.__midnight, c=m.state.caseData;
      const gun=Object.values(c.clues).find(x=>x.type==='gun');
      m.state.found.add(gun.object);
      m.showScreen('accuse');
    });
    await page.waitForTimeout(400);
    const wi = await page.evaluate(() => (window.__midnight.state.caseData.killerIndex + 1) % 3);
    await page.click(`.accuse-row[data-index="${wi}"]`);
    await page.click('#btnMakeAccusation');
    await page.waitForTimeout(250);
    await page.click('#btnDoAccuse');
    await page.waitForTimeout(900);
    const wrong = await page.evaluate(() => ({ cls: document.querySelector('#screen-end').className, failure: window.__midnight.state.failure, stamp: document.querySelector('#vfStamp').textContent }));
    console.log('WRONG', w+'x'+h, JSON.stringify(wrong));
    assert(wrong.cls.includes('is-loss')); assert.equal(wrong.failure,'wrong');
    if (errors.length) console.log('PAGE ERRORS', errors);
    assert.equal(errors.length,0);
    await page.close();
  }
  await browser.close();
  console.log('ALL FLOW CHECKS PASSED');
})().catch(e => { console.error(e); process.exit(1); });
