  border-top:1px solid rgba(229,187,121,.32);
  box-shadow:0 -22px 70px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,221,165,.13);
}
.office-desk::before{
  content:"";position:absolute;inset:0;opacity:.36;
  background:
    repeating-linear-gradient(0deg,rgba(255,220,166,.08) 0 1px,transparent 1px 5px),
    repeating-linear-gradient(94deg,transparent 0 90px,rgba(0,0,0,.4) 90px 92px),
    repeating-linear-gradient(2deg,transparent 0 13px,rgba(0,0,0,.08) 13px 14px);
}
.office-desk::after{
  content:"";position:absolute;left:0;right:0;top:0;height:7px;
  background:linear-gradient(180deg,rgba(255,215,155,.08),transparent);
  border-bottom:1px solid rgba(0,0,0,.35);
}
.office-desk .desk-grain{
  position:absolute;left:0;right:0;top:0;height:2px;
  background:linear-gradient(90deg,transparent,rgba(255,220,164,.5),transparent);
}
.desk-blotter{
  position:absolute;left:11%;right:8%;top:8%;height:64%;
  background:
    radial-gradient(ellipse at 26% 18%,rgba(146,164,120,.2),transparent 46%),
    repeating-linear-gradient(3deg,rgba(255,255,255,.022) 0 1px,transparent 1px 7px),
    linear-gradient(160deg,#243325,#101c14 58%,#09100b);
  border:1px solid rgba(201,174,117,.22);border-radius:3px;
  box-shadow:inset 0 0 24px rgba(0,0,0,.62),0 4px 12px rgba(0,0,0,.28);
  transform:rotate(-.6deg);opacity:.8;
}
.desk-file{
  position:absolute;left:47%;top:12%;width:23%;height:31%;
  background:linear-gradient(150deg,#d6c5a4,#a58f6c 72%,#8b7656);
  box-shadow:0 3px 7px rgba(0,0,0,.46),inset 0 1px 0 rgba(255,255,255,.34);
  transform:rotate(7deg);opacity:.2;
}
.desk-file::before{
  content:"";position:absolute;inset:14% 10%;border-top:1px solid #5c4a31;border-bottom:1px solid #5c4a31;opacity:.5;
}
.desk-ashtray{
  position:absolute;left:41%;top:3%;width:9%;height:17%;border-radius:50%;
  background:radial-gradient(ellipse at 44% 38%,#3b3730,#171512 62%,#080706);
  border:1px solid rgba(193,170,126,.3);box-shadow:0 3px 8px rgba(0,0,0,.55),inset 0 1px 1px rgba(255,255,255,.14);
  opacity:.7;
}
.desk-ashtray i{
  position:absolute;left:34%;top:28%;width:34%;height:34%;border-radius:50%;
  border:1px solid rgba(10,8,6,.8);background:radial-gradient(circle at 40% 35%,#544b3d,#15110d);
}
.office-lamp{
  position:absolute;left:1.5%;bottom:28%;width:34%;z-index:2;
  transform:rotate(-1deg);filter:drop-shadow(0 18px 22px rgba(0,0,0,.58));
  pointer-events:none;
}
.lamp-glow{
  position:absolute;left:50%;top:29%;width:330%;height:158%;transform:translateX(-50%);
  background:radial-gradient(ellipse at 50% 31%,rgba(255,199,112,.31),rgba(214,134,53,.11) 44%,transparent 71%);
  filter:blur(12px);pointer-events:none;
  animation:lampBreathe 5.5s ease-in-out infinite;
}
.lamp-svg{display:block;width:100%;height:auto;overflow:visible}
@keyframes lampBreathe{0%,100%{opacity:.88}48%{opacity:1}53%{opacity:.93}57%{opacity:1}}
.phone-zone{
  position:absolute;right:1.5%;bottom:25.5%;width:63%;z-index:3;padding:0;border:0;
  background:none;cursor:pointer;pointer-events:auto;-webkit-appearance:none;appearance:none;
  transform-origin:50% 90%;
  filter:drop-shadow(0 24px 24px rgba(0,0,0,.72)) brightness(1.1);
  transition:filter .25s;
}
.phone-zone::before{
  content:"";position:absolute;left:6%;right:6%;bottom:-1%;height:56%;z-index:-1;
  background:radial-gradient(ellipse at 50% 78%,rgba(255,197,111,.23),transparent 70%);
  filter:blur(16px);pointer-events:none;
}
.phone-zone:hover,.phone-zone:focus-visible{filter:drop-shadow(0 24px 28px rgba(0,0,0,.75)) brightness(1.18)}
.screen-office.is-ringing .phone-zone{animation:phoneRing 3.4s cubic-bezier(.36,.07,.19,.97) infinite}
.screen-office.is-ringing .phone-zone::before{animation:phoneHalo 3.4s ease-in-out infinite}
.screen-office.is-answered .phone-zone{cursor:default;filter:drop-shadow(0 24px 24px rgba(0,0,0,.72)) brightness(1.06)}
.phone-svg{display:block;width:100%;height:auto;overflow:visible}
.phone-handset{
  transform-box:view-box;transform-origin:140px 76px;
  transition:transform .5s cubic-bezier(.2,.9,.2,1);
}
.screen-office.is-answered .phone-handset{transform:translateY(-13px) rotate(-5deg)}
.phone-hint{
  position:absolute;left:50%;top:-9%;transform:translateX(-50%);z-index:4;
  padding:5px 8px;white-space:nowrap;
  border:1px solid rgba(201,161,94,.42);background:rgba(9,7,5,.86);
  font-family:var(--ui);font-size:6.5px;font-weight:500;letter-spacing:.2em;color:var(--gold-bright);
  box-shadow:0 8px 20px rgba(0,0,0,.5);
  animation:tapPulse 2.2s ease-in-out infinite;
  transition:opacity .35s,visibility .35s;
}
.phone-hint::after{
  content:"";position:absolute;left:50%;bottom:-4px;width:6px;height:6px;
  background:rgba(9,7,5,.9);border-right:1px solid rgba(201,161,94,.42);border-bottom:1px solid rgba(201,161,94,.42);
  transform:translateX(-50%) rotate(45deg);
}
.screen-office.is-answered .phone-hint{opacity:0;visibility:hidden}
@keyframes tapPulse{0%,100%{opacity:.62;transform:translate(-50%,0)}50%{opacity:1;transform:translate(-50%,-3px)}}
@keyframes phoneHalo{0%,32%,100%{opacity:.45}7%,17%{opacity:.95}}
@keyframes phoneRing{
  0%,30%,100%{transform:rotate(-1.2deg) translate(0,0)}
  2%{transform:rotate(-2.9deg) translate(-1px,-1px)}
  5%{transform:rotate(-.2deg) translate(2px,0)}
  8%{transform:rotate(-2.7deg) translate(-2px,-1px)}
  11%{transform:rotate(-.4deg) translate(2px,0)}
  14%{transform:rotate(-2.5deg) translate(-1px,0)}
  18%{transform:rotate(-1.2deg) translate(0,0)}
  24%{transform:rotate(-1.6deg) translate(0,0)}
}
.ring-arcs{position:absolute;left:54%;top:10%;width:10px;height:10px;z-index:-1;pointer-events:none}
.ring-arcs span{
  position:absolute;left:0;top:0;width:60px;height:60px;margin:-30px 0 0 -30px;
  border:1px solid rgba(227,194,134,.7);border-radius:50%;opacity:0;
  animation:ringPulse 3.4s ease-out infinite;
}
.ring-arcs span:nth-child(2){animation-delay:.16s}
.ring-arcs span:nth-child(3){animation-delay:.32s}
@keyframes ringPulse{0%{transform:scale(.2);opacity:0}2%{opacity:.55}19%{transform:scale(2.7);opacity:0}20%,100%{opacity:0}}
.screen-office.is-answered .ring-arcs{display:none}

