content.text:
Now audio rewrite. Replace `startRing` guard and `ringBurst`. Let's craft. Need no async issue.

Current startRing:
```
startRing() {
 if (!this.enabled || !this.ctx || state.screen !== 'office' || this.ringTimer) return;
 this.ringBurst(0);
 this.ringTimer = setInterval(() => {
   if (!this.enabled || state.screen !== 'office') { this.stopRing(); return; }
   this.ringBurst(0);
 }, 3400);
},
```
Change guard add `state.call.answered`. In interval also stop if answered.
ringBurst:
```
ringBurst(delay=0) {
 if(!this.ctx) return;
 const ctx=this.ctx;
 const t=ctx.currentTime+delay;
 const bell=ctx.createGain();
 bell.gain.setValueAtTime(0.0001,t);
 bell.gain.exponentialRampToValueAtTime(0.052,t+0.035);
 bell.gain.setValueAtTime(0.052,t+0.64);
 bell.gain.exponentialRampToValueAtTime(0.0001,t+1.04);
 const band=ctx.createBiquadFilter(); band.type='bandpass'; band.frequency.value=1450; band.Q.value=.75;
 bell.connect(band).connect(this.master);
 [[1046,.6,'triangle'],[1470,.26,'sine'],[2190,.12,'sine']].forEach...
  osc.frequency.setValueAtTime(freq*1.006,t);
  osc.frequency.exponentialRampToValueAtTime(freq,t+0.35);
  gain node value amp, oscillator->partialGain->bell.
 // tremolo
 const lfo=ctx.createOscillator(); lfo.type='sine'; lfo.frequency.value=19;
 const lfoDepth=ctx.createGain(); lfoDepth.gain.value=0.014;
 lfo.connect(lfoDepth).connect(bell.gain);
 lfo.start(t); lfo.stop(t+1.05);
 // mechanical clapper noise
 const buffer = ctx.createBuffer(1, ctx.sampleRate*0.08, ctx.sampleRate); data...
 const src = ctx.createBufferSource(); src.buffer=buffer;
 const bp=ctx.createBiquadFilter(); bp.type='bandpass'; bp.frequency.value=2200; bp.Q.value=1;
 const ng=ctx.createGain(); ng.gain.setValueAtTime(.012,t); ng.gain.exponentialRampToValueAtTime(.0001,t+.07);
 src.connect(bp).connect(ng).connect(this.master); src.start(t); src.stop(t+.08);
}
```
One concern lfo modulation on bell.gain (envelope) could be added after exponential ramp ends. We start lfo and stop at 1.05; modulation amplitude .014 on top of decaying envelope; after envelope at .0001, modulation could go negative (gain can be negative = phase invert but low). Fine. Could route LFO through gain into a separate tremolo gain node; but okay.

`pickup()`:
```
pickup(){
 if(!this.enabled||!this.ctx)return;
 const ctx...
 const t...
 // click noise and low thunk
 const osc=...
 ...
 // line hiss 0.18 sec
 noise buffer...
}
```
Actually `enabled` guard. `answerPhone` calls `Sfx.pickup()` even if not enabled; no effect.

Add method before tick.

Let's patch.

input.newString:
startRing() {
  if (!this.enabled || !this.ctx || state.screen !== 'office' || state.call.answered || this.ringTimer) return;
  this.ringBurst(0);
  this.ringTimer = setInterval(() => {
    if (!this.enabled || state.screen !== 'office' || state.call.answered) { this.stopRing(); return; }
    this.ringBurst(0);
  }, 3400);
},
stopRing() {
  if (this.ringTimer) clearInterval(this.ringTimer);
  this.ringTimer = null;
},
ringBurst(delay) {
  if (!this.ctx) return;
  const ctx = this.ctx;
  const t = ctx.currentTime + delay;
  const bell = ctx.createGain();
  bell.gain.setValueAtTime(0.0001, t);
  bell.gain.exponentialRampToValueAtTime(0.055, t + 0.035);
  bell.gain.setValueAtTime(0.052, t + 0.66);
  bell.gain.exponentialRampToValueAtTime(0.0001, t + 1.06);
  const band = ctx.createBiquadFilter();
  band.type = 'bandpass';
  band.frequency.value = 1450;
  band.Q.value = 0.7;
  bell.connect(band).connect(this.master);
  [[1046, 0.62, 'triangle'], [1470, 0.27, 'sine'], [2190, 0.11, 'sine']].forEach(([freq, amp, type]) => {
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq * 1.007, t);
    osc.frequency.exponentialRampToValueAtTime(freq, t + 0.34);
    const partial = ctx.createGain();
    partial.gain.value = amp;
    osc.connect(partial).connect(bell);
    osc.start(t);
    osc.stop(t + 1.08);
  });
  const lfo = ctx.createOscillator();
  lfo.type = 'sine';
  lfo.frequency.value = 19;
  const lfoDepth = ctx.createGain();
  lfoDepth.gain.value = 0.014;
  lfo.connect(lfoDepth).connect(bell.gain);
  lfo.start(t);
  lfo.stop(t + 1.07);
  const clickBuffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * 0.07), ctx.sampleRate);
  const clickData = clickBuffer.getChannelData(0);
  for (let i = 0; i < clickData.length; i++) {
    clickData[i] = (Math.random() * 2 - 1) * (1 - i / clickData.length);
  }
  const click = ctx.createBufferSource();
  click.buffer = clickBuffer;
  const clickFilter = ctx.createBiquadFilter();
  clickFilter.type = 'bandpass';
  clickFilter.frequency.value = 2400;
  clickFilter.Q.value = 1.1;
  const clickGain = ctx.createGain();
  clickGain.gain.setValueAtTime(0.014, t);
  clickGain.gain.exponentialRampToValueAtTime(0.0001, t + 0.065);
  click.connect(clickFilter).connect(clickGain).connect(this.master);
  click.start(t);
  click.stop(t + 0.08);
},
pickup() {
  if (!this.enabled || !this.ctx) return;
  const ctx = this.ctx;
  const t = ctx.currentTime;
  const thunk = ctx.createOscillator();
  thunk.type = 'triangle';
  thunk.frequency.setValueAtTime(190, t);
  thunk.frequency.exponentialRampToValueAtTime(92, t + 0.11);
  const thunkGain = ctx.createGain();
  thunkGain.gain.setValueAtTime(0.0001, t);
  thunkGain.gain.linearRampToValueAtTime(0.03, t + 0.008);
  thunkGain.gain.exponentialRampToValueAtTime(0.0001, t + 0.15);
  thunk.connect(thunkGain).connect(this.master);
  thunk.start(t);
  thunk.stop(t + 0.17);
  const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * 0.24), ctx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * 0.55;
  const staticSrc = ctx.createBufferSource();
  staticSrc.buffer = buffer;
  const filter = ctx.createBiquadFilter();
  filter.type = 'bandpass';
  filter.frequency.value = 1250;
  filter.Q.value = 0.8;
  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.012, t + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
  staticSrc.connect(filter).connect(gain).connect(this.master);
  staticSrc.start(t + 0.02);
  staticSrc.stop(t + 0.25);
},

