  }));
  console.log('ANSWERED',w+'x'+h,JSON.stringify(answered));
  assert(answered.answered); assert(!answered.timer); assert.equal(answered.status,'CONNECTED');
  assert(answered.line.length>20); assert.equal(answered.step,'LINE 1 / 3'); assert.equal(answered.hint,'hidden'); assert(answered.sceneDisabled);
