import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
for (const [w, h] of [[320, 568], [360, 640], [375, 667]]) {
  const page = await browser.newPage({ viewport: { width: w, height: h } });
  await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
  await page.waitForTimeout(400);
  const rows = await page.evaluate(() => {
    const all = LOCATIONS.slice();
    const out = [];
    for (const loc of all) {
      previousLocation = null;
      LOCATIONS.length = 0; LOCATIONS.push(loc);
      state.caseData = makeCase();
      LOCATIONS.length = 0; LOCATIONS.push(...all);
      state.found = new Set(); renderCase(); showScreen('scene');
      const q = (s) => document.querySelector(s).getBoundingClientRect();
      const h2 = document.querySelector('#scenePlace');
      const chip = document.querySelector('.scene-hud .board-chip').getBoundingClientRect();
      const hud = document.querySelector('.scene-hud').getBoundingClientRect();
      const art = document.querySelector('#sceneArt').getBoundingClientRect();
      const foot = document.querySelector('.scene-foot').getBoundingClientRect();
      const brief = document.querySelector('#sceneBrief');
      const br = brief.getBoundingClientRect();
      out.push({
        scene: loc.scene, name: loc.name,
        titleH: Math.round(document.querySelector('#scenePlace').getBoundingClientRect().height),
        titleW: Math.round(document.querySelector('#scenePlace').getBoundingClientRect().width),
        chipOverlap: document.querySelector('#scenePlace').getBoundingClientRect().right > chip.left && h2.offsetTop < chip.bottom,
        artOverFoot: Math.round(art.bottom - foot.top),
        artBottom: Math.round(art.bottom), footTop: Math.round(foot.top), footBottom: Math.round(foot.bottom),
        briefH: Math.round(br.height),
        scrollH: document.documentElement.scrollHeight, clientH: document.documentElement.clientHeight
      });
    }
    previousLocation = null;
    return out;
  });
  console.log(`\n=== ${w}x${h} ===`);
  rows.forEach((r) => {
    const issues = [];
    if (r.chipOverlap) issues.push('CHIP');
    if (r.artOverFoot > 0) issues.push('ART>FOOT');
    if (r.scrollH > r.clientH + 1) issues.push('SCROLL');
    console.log(`${issues.length ? 'BAD ' : 'OK  '} ${r.scene.padEnd(12)} title ${r.titleW}x${r.titleH} brief ${r.briefH} artBottom ${r.artBottom} foot ${r.footTop}-${r.footBottom} ${issues.join(',')}`);
  });
  await page.close();
}
await browser.close();
