import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(400);
const scenes = ['pier9','marlowe','diner','casino'];
for (const sceneName of scenes) {
  await page.evaluate((s) => {
    const all=LOCATIONS.slice(); const target=all.find(l=>l.scene===s);
    previousLocation=null; LOCATIONS.length=0; LOCATIONS.push(target);
    state.caseData=makeCase(); LOCATIONS.length=0; LOCATIONS.push(...all);
    state.found=new Set(); renderCase(); showScreen('scene');
  }, sceneName);
  await page.waitForTimeout(900);
  for (const key of ['desk','window','coat','safe']) {
    const info = await page.evaluate((key) => {
      const c=state.caseData, spec=SCENES[c.location.scene], st=spec.stations[key], def=STATIONS[st.t];
      const host=document.createElement('div');host.style.cssText='position:absolute;left:-9999px;top:0;width:400px;height:500px';
      host.innerHTML=`<svg viewBox="0 0 400 500" xmlns="http://www.w3.org/2000/svg">${SCENE_DEFS}${def.draw(st,key)}</svg>`;
      document.body.appendChild(host);
      const g=host.querySelector('svg > g:last-of-type'); const b=g.getBBox(); host.remove();
      const target = key==='desk'?205:key==='window'?180:key==='coat'?120:150;
      const world={x:b.x+st.x,y:b.y+st.y,w:b.width,h:b.height};
      const cx=world.x+world.w/2, cy=world.y+world.h/2;
      let W=Math.max(target, world.w*1.18), H=W*1.25;
      if (H < world.h*1.18) { H=world.h*1.18; W=H*.8; }
      let x=cx-W/2, y=cy-H/2;
      x=Math.max(0,Math.min(400-W,x)); y=Math.max(0,Math.min(500-H,y));
      const div=document.createElement('div'); div.innerHTML=renderScene(c.location);
      const el=div.querySelector('svg'); el.setAttribute('viewBox',`${x} ${y} ${W} ${H}`);
      document.querySelector('#zoomCanvas').innerHTML=div.innerHTML;
      showScreen('zoom');
      return {target,W,H,x,y,b,world};
    }, key);
    await page.waitForTimeout(650);
    await page.screenshot({ path: `/tmp/opencode/shots/crop2-${sceneName}-${key}.png` });
    console.log(sceneName,key,JSON.stringify(info));
  }
}
await browser.close();
EOF
