input.content:
/* ============================================================
   MIDNIGHT DETECTIVE — CLOSE-UP CAMERA
   Builds a genuine macro view from the room that was just on
   screen. The inspected station is kept pixel-for-pixel, the
   room behind it is softened, and the crop frames the object.
   ============================================================ */

const CLOSEUP_DEFS = `
<defs>
  <filter id="cz-bg-blur" x="-18%" y="-18%" width="136%" height="136%">
    <feGaussianBlur stdDeviation="4.6"/>
  </filter>
  <radialGradient id="cz-glow" cx=".5" cy=".5" r=".5">
    <stop offset="0" stop-color="var(--accent)" stop-opacity=".28"/>
    <stop offset=".42" stop-color="var(--accent)" stop-opacity=".13"/>
    <stop offset="1" stop-color="#000" stop-opacity="0"/>
  </radialGradient>
  <radialGradient id="cz-vignette" cx=".5" cy=".46" r=".76">
    <stop offset=".34" stop-color="#000" stop-opacity="0"/>
    <stop offset=".7" stop-color="#000" stop-opacity=".24"/>
    <stop offset="1" stop-color="#000" stop-opacity=".8"/>
  </radialGradient>
  <linearGradient id="cz-sheen" x1="0" y1="0" x2=".9" y2="1">
    <stop offset="0" stop-color="#fff" stop-opacity=".07"/>
    <stop offset=".38" stop-color="#fff" stop-opacity=".012"/>
    <stop offset=".62" stop-color="#000" stop-opacity="0"/>
    <stop offset="1" stop-color="#000" stop-opacity=".24"/>
  </linearGradient>
  <radialGradient id="cz-cold" cx=".5" cy=".5" r=".5">
    <stop offset="0" stop-color="#b7d9df" stop-opacity=".22"/>
    <stop offset=".5" stop-color="#7faeb7" stop-opacity=".08"/>
    <stop offset="1" stop-color="#000" stop-opacity="0"/>
  </radialGradient>
</defs>`;

const CLOSEUP_FALLBACK = {
  desk: { w: 148, h: 88 },
  window: { w: 112, h: 70 },
  coat: { w: 78, h: 108 },
  safe: { w: 100, h: 88 }
};

const closeupHash = (seed) => {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
};

const closeupRandom = (seed) => {
  let h = closeupHash(seed);
  return () => {
    h = (Math.imul(h, 1664525) + 1013904223) >>> 0;
    return h / 4294967296;
  };
};

function getCloseupFrame(loc, key, ratio = 0.62) {
  const source = document.querySelector('#sceneCanvas svg');
  const group = source?.querySelector(`[data-station="${key}"]`);
  let box = null;
  if (group) {
    try {
      const b = group.getBBox();
      if (b.width > 2 && b.height > 2) {
        box = { x: b.x, y: b.y, w: b.width, h: b.height };
      }
    } catch (e) { /* fall through to the station's nominal size */ }
  }
  if (!box) {
    const spec = SCENES[loc.scene] || {};
    const st = spec.stations?.[key] || { x: 200, y: 280 };
    const fb = CLOSEUP_FALLBACK[key] || { w: 120, h: 100 };
    const s = st.s || 1;
    box = { x: st.x - (fb.w * s) / 2, y: st.y - (fb.h * s) / 2, w: fb.w * s, h: fb.h * s };
  }

  // The zoom bay changes shape from phone to phone. Match its aspect so
  // the same crop that is drawn is the crop that fills the bay.
  const ar = Math.max(0.46, Math.min(2.5, ratio || 0.62));
  const maxW = 0.88;
  const maxH = 0.80;
  let w = Math.max(box.w / maxW, (box.h / maxH) * ar, 70);
  let h = w / ar;
  const cx = box.x + box.w / 2;
  const cy = box.y + box.h / 2;
  return {
    x: cx - w / 2,
    y: cy - h / 2,
    w,
    h,
    ar,
    cx,
    cy,
    box
  };
}

function closeupDust(frame, seed) {
  const rnd = closeupRandom(seed);
  let out = '<g fill="var(--chalk)">';
  for (let i = 0; i < 16; i++) {
    const x = frame.x + rnd() * frame.w;
    const y = frame.y + rnd() * frame.h;
    const r = 0.35 + rnd() * 0.9;
    const o = 0.05 + rnd() * 0.15;
    out += `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="${r.toFixed(2)}" opacity="${o.toFixed(2)}"/>`;
  }
  return out + '</g>';
}

function renderCloseup(loc, key, ratio = 0.62) {
  const spec = SCENES[loc.scene] || {};
  const pal = SCENE_PALETTES[spec.palette || loc.scene] || SCENE_PALETTES.hotel;
  const frame = getCloseupFrame(loc, key, ratio);
  const source = document.querySelector('#sceneCanvas svg');
  let hero = '';
  let backdrop = '';

  if (source) {
    const clone = source.cloneNode(true);
    const heroNode = clone.querySelector(`[data-station="${key}"]`);
    if (heroNode) {
      hero = heroNode.outerHTML;
      heroNode.remove();
    }
    clone.querySelectorAll('defs').forEach((node) => node.remove());
    clone.querySelectorAll('rect[fill="url(#rs-vignette)"]').forEach((node) => node.remove());
    backdrop = clone.innerHTML;
  }

  if (!hero) {
    const st = spec.stations?.[key];
    const def = st && STATIONS[st.t];
    hero = def ? `<g data-station="${key}">${def.draw(st, key)}</g>` : '';
  }

  const isFloorSafe = ['floorSafe', 'strongbox', 'trunk'].includes(spec.stations?.[key]?.t);
  const base = key === 'desk'
    ? 'var(--floor)'
    : key === 'window'
      ? 'var(--wall)'
      : isFloorSafe ? 'var(--floor)' : 'var(--wall)';
  const frameRect = `x="${frame.x}" y="${frame.y}" width="${frame.w}" height="${frame.h}"`;
  const glowRx = Math.max(frame.box.w * 1.25, frame.w * 0.34);
  const glowRy = Math.max(frame.box.h * 1.2, frame.h * 0.26);
  const dust = closeupDust(frame, `${loc.scene}:${key}`);
  const coldGlow = key === 'window'
    ? `<ellipse cx="${frame.cx}" cy="${frame.cy}" rx="${(glowRx * 1.1).toFixed(1)}" ry="${(glowRy * 1.05).toFixed(1)}" fill="url(#cz-cold)" opacity=".8"/>`
    : '';

  const svg = `<svg class="closeup-svg" viewBox="${frame.x.toFixed(2)} ${frame.y.toFixed(2)} ${frame.w.toFixed(2)} ${frame.h.toFixed(2)}" preserveAspectRatio="xMidYMid slice" aria-hidden="true" style="${sceneVars(pal)}">
    ${SCENE_DEFS}
    ${CLOSEUP_DEFS}
    <rect ${frameRect} fill="${base}"/>
    <g filter="url(#cz-bg-blur)" opacity=".9">${backdrop}</g>
    <rect ${frameRect} fill="#050403" opacity=".3"/>
    <ellipse cx="${frame.cx.toFixed(1)}" cy="${frame.cy.toFixed(1)}" rx="${Math.max(frame.box.w * 0.8, frame.w * 0.2).toFixed(1)}" ry="${Math.max(frame.box.h * 0.85, frame.h * 0.14).toFixed(1)}" fill="url(#cz-glow)"/>
    ${coldGlow}
    ${hero}
    <rect ${frameRect} fill="url(#cz-sheen)"/>
    ${dust}
    <rect ${frameRect} fill="url(#cz-vignette)"/>
  </svg>`;

  return { svg, frame };
}

