import { createRequire } from 'node:module';
import { join } from 'node:path';
import { mkdirSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const OUT = '/tmp/opencode/shots/audit';
mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });

await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(500);

const scenes = await page.evaluate(() => LOCATIONS.map((l) => l.scene));
const rows = [];

for (const sceneName of scenes) {
  await page.evaluate((s) => {
    const all = LOCATIONS.slice();
    const target = all.find((l) => l.scene === s);
    previousLocation = null;
    LOCATIONS.length = 0;
    LOCATIONS.push(target);
    state.caseData = makeCase();
    LOCATIONS.length = 0;
    LOCATIONS.push(...all);
    state.found = new Set();
    renderCase();
    showScreen('scene');
  }, sceneName);
  await page.waitForTimeout(750);

  for (const key of ['desk', 'window', 'coat', 'safe']) {
    await page.evaluate((k) => openObject(k), key);
    await page.waitForTimeout(1050);

    const info = await page.evaluate((k) => {
      const svg = document.querySelector('#zoomCanvas svg');
      const vb = svg ? (svg.getAttribute('viewBox') || '').trim().split(/\s+/).map(Number) : null;
      const meta = state.zoomMeta;
      const station = svg?.querySelector(`[data-station="${k}"]`);
      let bb = null;
      if (station) {
        try {
          const b = station.getBBox();
          bb = { x: b.x, y: b.y, w: b.width, h: b.height };
        } catch (e) {}
      }
      const clue = document.querySelector('#clueText')?.textContent?.trim() || '';
      return {
        screen: state.screen,
        vb,
        frame: meta ? { x: meta.frame.x, y: meta.frame.y, w: meta.frame.w, h: meta.frame.h, ar: meta.frame.ar, zoom: meta.zoom } : null,
        box: meta ? meta.frame.box : null,
        bb,
        stations: svg ? svg.querySelectorAll('[data-station]').length : 0,
        object: document.querySelector('#zoomObject')?.textContent,
        mag: document.querySelector('#zoomMag')?.textContent,
        clueLen: clue.length,
        transit: document.querySelector('#zoomTransit').className,
        screenClass: document.querySelector('#screen-zoom').className
      };
    }, key);

    const problems = [];
    if (!info.vb) problems.push('no closeup svg');
    if (!info.frame) problems.push('no frame');
    if (info.screen !== 'zoom') problems.push('not on zoom screen');
    if (info.stations !== 1) problems.push(`station count ${info.stations}`);
    if (info.clueLen < 25) problems.push('short clue');
    if (info.vb && info.frame) {
      const d = [
        Math.abs(info.vb[0] - info.frame.x),
        Math.abs(info.vb[1] - info.frame.y),
        Math.abs(info.vb[2] - info.frame.w),
        Math.abs(info.vb[3] - info.frame.h)
      ];
      if (Math.max(...d) > 0.25) problems.push(`viewBox mismatch ${JSON.stringify(info.vb)} vs frame`);
      const b = info.box;
      if (b) {
        const padL = b.x - info.frame.x;
        const padR = info.frame.x + info.frame.w - (b.x + b.w);
        const padT = b.y - info.frame.y;
        const padB = info.frame.y + info.frame.h - (b.y + b.h);
        if (Math.min(padL, padR, padT, padB) < -0.5) problems.push(`object clipped ${JSON.stringify({ padL, padR, padT, padB })}`);
        if (b.w / info.frame.w < 0.4 || b.h / info.frame.h < 0.4) problems.push(`object too small ${(b.w / info.frame.w).toFixed(2)}x${(b.h / info.frame.h).toFixed(2)}`);
      }
    }
    const path = `${OUT}/${sceneName}-${key}.png`;
    await page.locator('#zoomArt').screenshot({ path });

    rows.push({ sceneName, key, info, problems });
    console.log(`${sceneName.padEnd(11)} ${key.padEnd(6)} ${info.object || '?'} ${info.mag || ''} ${problems.length ? 'PROBLEMS: ' + problems.join('; ') : 'ok'}`);
    if (problems.length) console.log('   ', JSON.stringify(info));
    await page.evaluate(() => goScene());
    await page.waitForTimeout(250);
  }
}

await browser.close();

const bad = rows.filter((r) => r.problems.length);
console.log(`\nAUDIT: ${rows.length} close-ups, ${bad.length} with problems`);
console.log('errors', errors.length ? errors : 'none');
process.exitCode = bad.length || errors.length ? 1 : 0;

import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readdirSync, writeFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const AUDIT = '/tmp/opencode/shots/audit';
const SCENES = '/tmp/opencode/shots/scenes';
const auditFiles = readdirSync(AUDIT).filter((f) => f.endsWith('.png'));
const sceneNames = [...new Set(auditFiles.map((f) => f.replace(/-(desk|window|coat|safe)\.png$/, '')))];
const sceneShots = readdirSync(SCENES).filter((f) => f.endsWith('.png'));
const shotFor = (name) => sceneShots.find((f) => f.endsWith(`-${name}.png`));

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const rows = sceneNames.map((name) => {
  const img = shotFor(name);
  const cells = ['desk', 'window', 'coat', 'safe'].map((k) => `
    <figure><img src="file://${AUDIT}/${name}-${k}.png"><figcaption>${k}</figcaption></figure>`).join('');
  return `<section class="row"><div class="scene"><img src="file://${SCENES}/${img}"><span>${name}</span></div>${cells}</section>`;
});

const sheet = (title, content) => `<!doctype html><html><head><meta charset="utf-8"><style>
  body{margin:0;background:#141210;color:#e9ddc4;font:13px/1.2 monospace}
  h1{font-size:15px;letter-spacing:.2em;margin:10px 14px}
  .row{display:flex;align-items:flex-end;gap:8px;padding:4px 10px;border-bottom:1px solid #2a241e}
  .scene{position:relative;flex:0 0 auto}
  .scene img{height:210px;display:block;border:1px solid #4a3a28}
  .scene span{position:absolute;left:0;bottom:0;background:#000a;color:#e9ddc4;font-size:12px;padding:2px 5px}
  figure{margin:0;flex:1 1 0;min-width:0}
  figure img{height:210px;width:100%;object-fit:cover;display:block;border:1px solid #3a3128}
  figcaption{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#a99b82;text-align:center;padding-top:2px}
</style></head><body><h1>${title}</h1>${content}</body></html>`;

const browser = await chromium.launch({ headless: true });
for (let s = 0; s < 4; s++) {
  const chunk = rows.slice(s * 6, s * 6 + 6).join('');
  const html = sheet(`CLOSE-UP AUDIT · SCENES ${s * 6 + 1}–${Math.min(24, s * 6 + 6)}`, chunk);
  const path = `/tmp/opencode/shots/sheet-${s + 1}.html`;
  writeFileSync(path, html);
  const page = await browser.newPage({ viewport: { width: 1180, height: 1450 }, deviceScaleFactor: 1 });
  await page.goto('file://' + path, { waitUntil: 'networkidle' });
  await page.waitForTimeout(250);
  await page.screenshot({ path: `/tmp/opencode/shots/closeup-sheet-${s + 1}.png`, fullPage: true });
  await page.close();
}
await browser.close();
console.log('scenes', sceneNames.join(', '));

import { createRequire } from 'node:module';
import { join } from 'node:path';
import { mkdirSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
mkdirSync('/tmp/opencode/shots/paused', { recursive: true });

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
