92: function closeupDust(frame, seed) {
93:   const rnd = closeupRandom(seed);
94:   let out = '<g fill="var(--chalk)">';
95:   for (let i = 0; i < 12; i++) {
96:     const x = frame.x + rnd() * frame.w;
97:     const y = frame.y + rnd() * frame.h;
98:     const r = 0.35 + rnd() * 0.9;
99:     const o = 0.035 + rnd() * 0.09;
100:     out += `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="${r.toFixed(2)}" opacity="${o.toFixed(2)}"/>`;
101:   }
102:   return out + '</g>';
103: }
104: 
105: function renderCloseup(loc, key, ratio = 0.62) {
106:   const spec = SCENES[loc.scene] || {};
107:   const pal = SCENE_PALETTES[spec.palette || loc.scene] || SCENE_PALETTES.hotel;
