118:     backdrop = clone.innerHTML;
119:   }
120: 
121:   if (!hasHero) {
122:     const st = spec.stations?.[key];
123:     const def = st && STATIONS[st.t];
124:     fallbackHero = def ? `<g data-station="${key}">${def.draw(st, key)}</g>` : '';
125:   }
126: 
127:   const stType = spec.stations?.[key]?.t || '';
128:   const floorSafe = ['floorSafe', 'strongbox', 'trunk'].includes(stType);
129:   const counterTop = ['register', 'till', 'cashBox', 'cage'].includes(stType);
130:   const onFloor = key === 'desk' || floorSafe || counterTop;
131:   const base = onFloor ? 'var(--floor)' : 'var(--wall)';
132:   const pattern = onFloor
133:     ? (SCENE_FLOORS[spec.floor] || SCENE_FLOORS.wood)
134:     : (SCENE_WALLS[spec.wall] || SCENE_WALLS.panel);
135:   const frameRect = `x="${frame.x}" y="${frame.y}" width="${frame.w}" height="${frame.h}"`;
136:   const dust = closeupDust(frame, `${loc.scene}:${key}`);
137:   // A soft hole in the lens shade: the inspected object keeps its exact
138:   // scene brightness, while the room around it falls away.
139:   const pad = Math.max(2.5, Math.min(frame.box.w, frame.box.h) * 0.035);
140:   const hole = `x="${(frame.box.x - pad).toFixed(2)}" y="${(frame.box.y - pad).toFixed(2)}" width="${(frame.box.w + pad * 2).toFixed(2)}" height="${(frame.box.h + pad * 2).toFixed(2)}"`;
