    selectSuspect(killerIndex);
    openConfirm();
    document.querySelector('#btnDoAccuse').click();
    return { screen: state.screen, failure: state.failure };
  });
  await page.waitForTimeout(500);
  check(await page.evaluate(() => state.screen === 'end'), `${w}x${h} accusation reaches end`, JSON.stringify(accused));
  check(await page.evaluate(() => document.scrollingElement.scrollHeight <= innerHeight), `${w}x${h} end no scroll`);

  check(errors.length === 0, `${w}x${h} no console/page errors`, JSON.stringify(errors));
  await page.close();
}

// Reduced motion should skip both camera animations.
{
