await page.waitForTimeout(500);

const scenes = await page.evaluate(() => LOCATIONS.map((l) => l.scene));
let count = 0;
const bad = [];
for (const sceneName of scenes) {
  await page.evaluate((s) => {
    const all = LOCATIONS.slice();
    const target = all.find((l) => l.scene === s);
    previousLocation = null;
    LOCATIONS.length = 0; LOCATIONS.push(target);
    state.caseData = makeCase();
    LOCATIONS.length = 0; LOCATIONS.push(...all);
    state.found = new Set();
    renderCase();
    showScreen('scene');
  }, sceneName);
  await page.waitForTimeout(420);

  for (const key of ['desk', 'window', 'coat', 'safe']) {
    await page.evaluate((k) => {
      state.currentObject = k;
      state.found.add(k);
      renderZoom();
      showScreen('zoom');
      window.__realSetTimeout = window.setTimeout;
      window.setTimeout = function (fn, ms, ...args) {
        if (ms === 800 || ms === 240) return 0;
        return window.__realSetTimeout(fn, ms, ...args);
      };
      goScene();
      // Drive the camera to the end of the pull-back without finishing.
      const frame = document.querySelector('#zoomTransitFrame');
      const veil = document.querySelector('.zoom-transit-veil');
      const zoom = document.querySelector('#screen-zoom');
      [...frame.getAnimations(), ...veil.getAnimations(), ...zoom.getAnimations()].forEach((a) => {
        a.pause();
        a.currentTime = 800;
      });
    }, key);

    const r = await page.evaluate((k) => {
      const rect = (el) => { const b = el.getBoundingClientRect(); return { x: b.x, y: b.y, w: b.width, h: b.height }; };
      const scene = document.querySelector('#sceneCanvas');
      const frame = document.querySelector('#zoomTransitFrame');
      const roomStation = document.querySelector(`#sceneCanvas [data-station="${k}"]`);
      const frameStation = frame.querySelector(`[data-station="${k}"]`);
      const closeStation = document.querySelector(`#zoomCanvas [data-station="${k}"]`);
      return {
        scene: rect(scene),
        frame: rect(frame),
        room: roomStation ? rect(roomStation) : null,
        frameStation: frameStation ? rect(frameStation) : null,
        close: closeStation ? rect(closeStation) : null,
        screen: state.screen,
        transit: document.querySelector('#zoomTransit').className,
        transform: getComputedStyle(frame).transform,
        sceneActive: document.querySelector('#screen-scene').classList.contains('is-active'),
        sceneInstant: document.querySelector('#screen-scene').classList.contains('is-instant')
      };
    }, key);

    count++;
    const problems = [];
    if (r.screen !== 'zoom') problems.push(`screen ${r.screen}`);
    if (!r.transit.includes('is-on')) problems.push('overlay off');
    if (!r.room || !r.frameStation) problems.push('missing station');
    if (!r.sceneActive || !r.sceneInstant) problems.push('scene not ready');
    if (Math.abs(r.frame.x - r.scene.x) > 0.6 || Math.abs(r.frame.y - r.scene.y) > 0.6) problems.push(`box origin ${r.frame.x - r.scene.x},${r.frame.y - r.scene.y}`);
    if (Math.abs(r.frame.w - r.scene.w) > 0.6 || Math.abs(r.frame.h - r.scene.h) > 0.6) problems.push(`box size ${r.frame.w - r.scene.w},${r.frame.h - r.scene.h}`);
    if (r.room && r.frameStation) {
      const d = [r.frameStation.x - r.room.x, r.frameStation.y - r.room.y, r.frameStation.w - r.room.w, r.frameStation.h - r.room.h].map(Math.abs);
      if (Math.max(...d) > 0.6) problems.push(`station ${d.map((v) => v.toFixed(2)).join(',')}`);
    }
    if (problems.length) {
      bad.push({ sceneName, key, problems });
      console.log('BAD', sceneName, key, problems.join('; '));
    }

    await page.evaluate(() => {
      window.setTimeout = window.__realSetTimeout;
      cancelZoomTransit();
      showScreen('scene');
    });
  }
}

console.log(`\nALIGNMENT: ${count} zoom-outs, ${bad.length} bad`);
console.log('errors', errors.length ? errors : 'none');
await browser.close();
process.exitCode = bad.length || errors.length ? 1 : 0;
EOF
