mkdir -p /tmp/opencode/audit && cat > /tmp/opencode/audit/layout-sweep.mjs <<'EOF'
import { createRequire } from 'node:module';
import { join } from 'node:path';
import { mkdirSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
mkdirSync('/tmp/opencode/audit/shots', { recursive: true });

const sizes = [[320, 480], [320, 568], [360, 640], [375, 667], [390, 844], [414, 896], [430, 932], [768, 1024]];
const browser = await chromium.launch({ headless: true });
let fails = 0;
const bad = (label, extra) => { fails++; console.log('BAD ', label, extra); };

for (const [w, h] of sizes) {
  const page = await browser.newPage({ viewport: { width: w, height: h } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
  await page.waitForTimeout(400);

  const probe = async (name) => page.evaluate((n) => {
    const doc = document.scrollingElement;
    const active = document.querySelector('.screen.is-active');
    const rect = active ? active.getBoundingClientRect() : null;
    return {
      screen: state.screen,
      scrollH: doc.scrollHeight,
      innerH: innerHeight,
      scrollW: doc.scrollWidth,
      innerW: innerWidth,
      active: active?.id,
      rect: rect ? [Math.round(rect.x), Math.round(rect.y), Math.round(rect.width), Math.round(rect.height)] : null
    };
  }, name);

  // office
  let p = await probe('office');
  if (p.scrollH > h + 1) bad(`${w}x${h} office vertical overflow`, JSON.stringify(p));
  if (p.scrollW > w + 1) bad(`${w}x${h} office horizontal overflow`, JSON.stringify(p));
  await page.screenshot({ path: `/tmp/opencode/audit/shots/${w}x${h}-1-office.png` });

  await page.evaluate(() => { answerPhone(); advanceCall(); advanceCall(); advanceCall(); goScene(); });
  await page.waitForTimeout(950);
  p = await probe('scene');
  if (p.scrollH > h + 1) bad(`${w}x${h} scene vertical overflow`, JSON.stringify(p));
  await page.screenshot({ path: `/tmp/opencode/audit/shots/${w}x${h}-2-scene.png` });

  // zoom (push-in then settled)
  await page.evaluate(() => openObject('window'));
  await page.waitForTimeout(1000);
  p = await probe('zoom');
  if (p.scrollH > h + 1) bad(`${w}x${h} zoom vertical overflow`, JSON.stringify(p));
  await page.screenshot({ path: `/tmp/opencode/audit/shots/${w}x${h}-3-zoom.png` });
  await page.evaluate(() => goScene());
  await page.waitForTimeout(1150);

  // all clues
  for (const key of ['desk', 'window', 'coat', 'safe']) {
    await page.evaluate((k) => openObject(k), key);
    await page.waitForTimeout(950);
    await page.evaluate(() => goScene());
    await page.waitForTimeout(1050);
  }
  p = await probe('scene-done');
  if (p.scrollH > h + 1) bad(`${w}x${h} scene-done vertical overflow`, JSON.stringify(p));

  await page.evaluate(() => goBoard());
  await page.waitForTimeout(700);
  p = await probe('board');
  if (p.scrollH > h + 1) bad(`${w}x${h} board vertical overflow`, JSON.stringify(p));
  await page.screenshot({ path: `/tmp/opencode/audit/shots/${w}x${h}-4-board.png` });

  await page.evaluate(() => { renderAccuse(); showScreen('accuse'); });
  await page.waitForTimeout(500);
  p = await probe('accuse');
  if (p.scrollH > h + 1) bad(`${w}x${h} accuse vertical overflow`, JSON.stringify(p));
  await page.screenshot({ path: `/tmp/opencode/audit/shots/${w}x${h}-5-accuse.png` });

  // win end
  await page.evaluate(() => { selectSuspect(state.caseData.killerIndex); openConfirm(); });
  await page.waitForTimeout(250);
  p = await probe('confirm');
  if (p.scrollH > h + 1) bad(`${w}x${h} confirm vertical overflow`, JSON.stringify(p));
  await page.screenshot({ path: `/tmp/opencode/audit/shots/${w}x${h}-6-confirm.png` });
  await page.click('#btnDoAccuse');
  await page.waitForTimeout(900);
  p = await probe('end-win');
  if (p.scrollH > h + 1) bad(`${w}x${h} end vertical overflow`, JSON.stringify(p));
  await page.screenshot({ path: `/tmp/opencode/audit/shots/${w}x${h}-7-end.png` });

  if (errors.length) bad(`${w}x${h} console`, JSON.stringify(errors));
  console.log(`${w}x${h} checked`);
  await page.close();
}
await browser.close();
console.log('FAILS', fails);
EOF
