Read file /home/runner/work/Midnight-Detective/Midnight-Detective/scene-closeups.js, lines 1-161
1: /* ============================================================
2:    MIDNIGHT DETECTIVE — CLOSE-UP CAMERA
3:    Builds a genuine macro view from the room that was just on
4:    screen. The inspected station keeps its exact scene art and
5:    brightness, the room around it falls into shadow, and the
6:    crop frames the object.
7:    ============================================================ */
8: 
9: const CLOSEUP_DEFS = `
10: <defs>
11:   <filter id="cz-feather" x="-60%" y="-60%" width="220%" height="220%">
12:     <feGaussianBlur stdDeviation="2.2"/>
13:   </filter>
14:   <radialGradient id="cz-vignette" cx=".5" cy=".48" r=".8">
15:     <stop offset=".46" stop-color="#000" stop-opacity="0"/>
16:     <stop offset=".76" stop-color="#000" stop-opacity=".16"/>
17:     <stop offset="1" stop-color="#000" stop-opacity=".62"/>
18:   </radialGradient>
19:   <linearGradient id="cz-sheen" x1="0" y1="0" x2=".9" y2="1">
20:     <stop offset="0" stop-color="#fff" stop-opacity=".04"/>
21:     <stop offset=".38" stop-color="#fff" stop-opacity=".008"/>
22:     <stop offset=".62" stop-color="#000" stop-opacity="0"/>
23:     <stop offset="1" stop-color="#000" stop-opacity=".14"/>
24:   </linearGradient>
25: </defs>`;
26: 
27: const CLOSEUP_FALLBACK = {
28:   desk: { w: 148, h: 88 },
29:   window: { w: 112, h: 70 },
30:   coat: { w: 78, h: 108 },
31:   safe: { w: 100, h: 88 }
32: };
33: 
34: const closeupHash = (seed) => {
35:   let h = 2166136261;
36:   for (let i = 0; i < seed.length; i++) {
37:     h ^= seed.charCodeAt(i);
38:     h = Math.imul(h, 16777619);
39:   }
40:   return h >>> 0;
41: };
42: 
43: const closeupRandom = (seed) => {
44:   let h = closeupHash(seed);
45:   return () => {
46:     h = (Math.imul(h, 1664525) + 1013904223) >>> 0;
47:     return h / 4294967296;
48:   };
49: };
50: 
51: function getCloseupFrame(loc, key, ratio = 0.62) {
52:   const source = document.querySelector('#sceneCanvas svg');
53:   const group = source?.querySelector(`[data-station="${key}"]`);
54:   let box = null;
55:   if (group) {
56:     try {
57:       const b = group.getBBox();
58:       if (b.width > 2 && b.height > 2) {
59:         box = { x: b.x, y: b.y, w: b.width, h: b.height };
60:       }
61:     } catch (e) { /* fall through to the station's nominal size */ }
62:   }
63:   if (!box) {
64:     const spec = SCENES[loc.scene] || {};
65:     const st = spec.stations?.[key] || { x: 200, y: 280 };
66:     const fb = CLOSEUP_FALLBACK[key] || { w: 120, h: 100 };
67:     const s = st.s || 1;
68:     box = { x: st.x - (fb.w * s) / 2, y: st.y - (fb.h * s) / 2, w: fb.w * s, h: fb.h * s };
69:   }
70: 
71:   // The zoom bay changes shape from phone to phone. Match its aspect so
72:   // the same crop that is drawn is the crop that fills the bay.
73:   const ar = Math.max(0.46, Math.min(2.5, ratio || 0.62));
74:   const maxW = key === 'coat' ? 0.8 : 0.88;
75:   const maxH = key === 'coat' ? 0.78 : 0.80;
76:   let w = Math.max(box.w / maxW, (box.h / maxH) * ar, 70);
77:   let h = w / ar;
78:   const cx = box.x + box.w / 2;
79:   const cy = box.y + box.h / 2;
80:   return {
81:     x: cx - w / 2,
82:     y: cy - h / 2,
83:     w,
84:     h,
85:     ar,
86:     cx,
87:     cy,
88:     box
89:   };
90: }
91: 
92: function closeupDust(frame, seed) {
93:   const rnd = closeupRandom(seed);
94:   let out = '<g fill="var(--chalk)">';
95:   for (let i = 0; i < 12; i++) {
96:     const x = frame.x + rnd() * frame.w;
97:     const y = frame.y + rnd() * frame.h;
98:     const r = 0.35 + rnd() * 0.9;
99:     const o = 0.035 + rnd() * 0.09;
100:     out += `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="${r.toFixed(2)}" opacity="${o.toFixed(2)}"/>`;
101:   }
102:   return out + '</g>';
103: }
104: 
105: function renderCloseup(loc, key, ratio = 0.62) {
106:   const spec = SCENES[loc.scene] || {};
107:   const pal = SCENE_PALETTES[spec.palette || loc.scene] || SCENE_PALETTES.hotel;
108:   const frame = getCloseupFrame(loc, key, ratio);
109:   const source = document.querySelector('#sceneCanvas svg');
110:   let fallbackHero = '';
111:   let backdrop = '';
112:   let hasHero = false;
113: 
114:   if (source) {
115:     const clone = source.cloneNode(true);
116:     hasHero = !!clone.querySelector(`[data-station="${key}"]`);
117:     clone.querySelectorAll('rect[fill="url(#rs-vignette)"]').forEach((node) => node.remove());
118:     backdrop = clone.innerHTML;
119:   }
120: 
121:   if (!hasHero) {
122:     const st = spec.stations?.[key];
123:     const def = st && STATIONS[st.t];
124:     fallbackHero = def ? `<g data-station="${key}">${def.draw(st, key)}</g>` : '';
125:   }
126: 
127:   const stType = spec.stations?.[key]?.t || '';
128:   const floorSafe = ['floorSafe', 'strongbox', 'trunk'].includes(stType);
129:   const counterTop = ['register', 'till', 'cashBox', 'cage'].includes(stType);
130:   const onFloor = key === 'desk' || floorSafe || counterTop;
131:   const base = onFloor ? 'var(--floor)' : 'var(--wall)';
132:   const pattern = onFloor
133:     ? (SCENE_FLOORS[spec.floor] || SCENE_FLOORS.wood)
134:     : (SCENE_WALLS[spec.wall] || SCENE_WALLS.panel);
135:   const frameRect = `x="${frame.x}" y="${frame.y}" width="${frame.w}" height="${frame.h}"`;
136:   const dust = closeupDust(frame, `${loc.scene}:${key}`);
137:   // A soft hole in the lens shade: the inspected object keeps its exact
138:   // scene brightness, while the room around it falls away.
139:   const pad = Math.max(2.5, Math.min(frame.box.w, frame.box.h) * 0.035);
140:   const hole = `x="${(frame.box.x - pad).toFixed(2)}" y="${(frame.box.y - pad).toFixed(2)}" width="${(frame.box.w + pad * 2).toFixed(2)}" height="${(frame.box.h + pad * 2).toFixed(2)}"`;
141:   const mask = `<mask id="cz-focus" maskUnits="userSpaceOnUse" x="${frame.x.toFixed(2)}" y="${frame.y.toFixed(2)}" width="${frame.w.toFixed(2)}" height="${frame.h.toFixed(2)}">
142:     <rect ${frameRect} fill="#fff"/>
143:     <rect ${hole} rx="6" fill="#000" filter="url(#cz-feather)"/>
144:   </mask>`;
145: 
146:   const svg = `<svg class="closeup-svg" viewBox="${frame.x.toFixed(2)} ${frame.y.toFixed(2)} ${frame.w.toFixed(2)} ${frame.h.toFixed(2)}" preserveAspectRatio="xMidYMid slice" aria-hidden="true" style="${sceneVars(pal)}">
147:     ${SCENE_DEFS}
148:     ${CLOSEUP_DEFS}
149:     ${mask}
150:     <rect ${frameRect} fill="${base}"/>
151:     <rect ${frameRect} fill="url(#${pattern})" opacity=".5"/>
152:     <g>${backdrop}</g>
153:     ${fallbackHero}
154:     <rect ${frameRect} fill="#050403" opacity=".58" mask="url(#cz-focus)"/>
155:     <rect ${frameRect} fill="url(#cz-sheen)"/>
156:     ${dust}
157:     <rect ${frameRect} fill="url(#cz-vignette)"/>
158:   </svg>`;
159: 
160:   return { svg, frame };
161: }

