cat > /tmp/opencode/audit/diner-pushin.mjs <<'EOF'
import { createRequire } from 'node:module';
import { join } from 'node:path';
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const OUT = '/tmp/opencode/audit/diner-pushin';
rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
const page = await context.newPage();
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(500);
await page.evaluate(() => {
  const all = LOCATIONS.slice();
  const target = all.find((l) => l.scene === 'diner');
  previousLocation = null;
  LOCATIONS.length = 0; LOCATIONS.push(target);
  state.caseData = makeCase();
  LOCATIONS.length = 0; LOCATIONS.push(...all);
  state.found = new Set();
  renderCase();
  showScreen('scene');
});
await page.waitForTimeout(900);

const cdp = await context.newCDPSession(page);
let frames = 0;
const meta = [];
cdp.on('Page.screencastFrame', ({ data, metadata, sessionId }) => {
  frames++;
  const file = `${OUT}/f-${String(frames).padStart(3, '0')}.jpg`;
  writeFileSync(file, Buffer.from(data, 'base64'));
  meta.push({ file, t: metadata.timestamp });
  cdp.send('Page.screencastFrameAck', { sessionId }).catch(() => {});
});
await cdp.send('Page.startScreencast', { format: 'jpeg', quality: 88, maxWidth: 390, maxHeight: 844, everyNthFrame: 1 });
await page.evaluate(() => openObject('window'));
await page.waitForTimeout(1150);
await cdp.send('Page.stopScreencast');
await page.waitForTimeout(200);
writeFileSync(`${OUT}/meta.json`, JSON.stringify(meta, null, 2));
console.log('frames', frames);
const pick = [8, 22, 32, 38, 44, 50, frames];
console.log('picks', pick.join(','));
await page.waitForTimeout(200);
await page.screenshot({ path: `${OUT}/settled.png` });
await browser.close();
EOF
