cat > /tmp/opencode/audit/objects.mjs <<'EOF'
import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(300);

const report = await page.evaluate(() => {
  const out = { cases: 0, badCount: [], dupes: [], repeats: [], noGun: [], badClue: [] };
  const seen = new Map();
  for (let i = 0; i < 180; i++) {
    startCase();
    const c = state.caseData;
    out.cases++;
    const n = c.objects.length;
    if (n < 3 || n > 8) out.badCount.push([c.location.name, n]);
    const keys = c.objects.map((o) => o.key);
    if (new Set(keys).size !== keys.length) out.dupes.push([c.location.name, keys]);
    const seq = seen.get(c.location.name) || [];
    if (seq.includes(n)) out.repeats.push([c.location.name, n, 'prior', seq.join(',')]);
    seq.push(n);
    seen.set(c.location.name, seq);
    const gun = Object.values(c.clues).filter((x) => x.type === 'gun');
    if (gun.length !== 1) out.noGun.push([c.location.name, n]);
    for (const k of keys) if (!c.clues[k] || !c.clues[k].text) out.badClue.push([c.location.name, k]);
  }
  out.sequences = [...seen.entries()].slice(0, 4).map(([k, v]) => [k, v.join(',')]);
  // force a run where counts max out
  const maxCase = (() => {
    for (let i = 0; i < 400; i++) { startCase(); if (state.caseData.objects.length === 8) return state.caseData; }
    return null;
  })();
  out.maxCount = maxCase ? maxCase.objects.length : 0;
  return out;
});
console.log(JSON.stringify(report, null, 1));

// layout pass at several sizes with the current case
for (const [w, h] of [[320, 480], [320, 568], [360, 640], [390, 844], [430, 932]]) {
  await page.setViewportSize({ width: w, height: h });
  await page.evaluate(() => { startCase(); goScene(); });
  await page.waitForTimeout(500);
  const m = await page.evaluate(() => {
    const art = document.querySelector('#sceneArt').getBoundingClientRect();
    const hs = [...document.querySelectorAll('.hotspot')].map((b) => {
      const r = b.getBoundingClientRect();
      return { key: b.dataset.object, x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1), inside: r.left >= art.left - 1 && r.right <= art.right + 1 && r.top >= art.top - 1 && r.bottom <= art.bottom + 1 };
    });
    return { count: hs.length, outside: hs.filter((x) => !x.inside), scrollH: document.scrollingElement.scrollHeight, innerH: innerHeight, art: { w: +art.width.toFixed(1), h: +art.height.toFixed(1) } };
  });
  console.log(w + 'x' + h, JSON.stringify(m));
}
console.log('ERRORS', JSON.stringify(errors));
await browser.close();
EOF
