const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(300);

async function caseWith(n) {
  return page.evaluate((n) => {
    for (let i = 0; i < 800; i++) {
      startCase();
      if (state.caseData.objects.length === n) {
        goScene();
        return { loc: state.caseData.location.name, objects: state.caseData.objects.map((o) => o.key) };
      }
    }
    return null;
  }, n);
}

for (const n of [3, 5, 8]) {
  const info = await caseWith(n);
  console.log('scene', n, JSON.stringify(info));
  await page.waitForTimeout(650);
  await page.screenshot({ path: `/tmp/opencode/shots2/scene-${n}.png` });
  // open an extra (non-core) object if present
  const extra = info.objects.find((k) => !['desk', 'window', 'coat', 'safe'].includes(k));
  if (extra) {
    await page.evaluate((k) => openObject(k), extra);
    await page.waitForTimeout(1300);
    await page.screenshot({ path: `/tmp/opencode/shots2/zoom-${n}-${extra}.png` });
    const z = await page.evaluate(() => ({ mag: document.querySelector('#zoomMag').textContent, art: document.querySelector('#zoomArt').getBoundingClientRect().toJSON() }));
    console.log('zoom', extra, JSON.stringify(z));
    await page.evaluate(() => goScene());
    await page.waitForTimeout(900);
  }
}

// board with max rows at multiple sizes
for (const [w, h] of [[320, 480], [390, 844]]) {
  await page.setViewportSize({ width: w, height: h });
  await page.evaluate(() => {
    for (let i = 0; i < 800; i++) { startCase(); if (state.caseData.objects.length === 8) break; }
    for (const o of state.caseData.objects) state.found.add(o.key);
    goBoard();
  });
  await page.waitForTimeout(700);
  const m = await page.evaluate(() => {
    const body = document.querySelector('.board-body');
    const list = document.querySelector('.clue-list');
    const rows = [...document.querySelectorAll('.clue-row')];
    const last = rows[rows.length - 1]?.getBoundingClientRect();
    const bodyR = body.getBoundingClientRect();
    const actions = document.querySelector('.board-actions').getBoundingClientRect();
    return {
      rows: rows.length,
      bodyH: +bodyR.height.toFixed(1),
      listH: +list.getBoundingClientRect().height.toFixed(1),
      listScroll: list.scrollHeight,
      lastBottom: last ? +last.bottom.toFixed(1) : 0,
      bodyBottom: +bodyR.bottom.toFixed(1),
      actionsTop: +actions.top.toFixed(1),
      scrollH: document.scrollingElement.scrollHeight,
      innerH: innerHeight
    };
  });
  console.log('board', w + 'x' + h, JSON.stringify(m));
  await page.screenshot({ path: `/tmp/opencode/shots2/board-8-${w}x${h}.png` });
}
console.log('ERRORS', JSON.stringify(errors));
await browser.close();
