function renderSearchSpots(key, plan, frame, bay) {
  const layer = $('#zoomSpots');
  layer.innerHTML = '';
  const frameEl = $('#zoomArt').getBoundingClientRect();
  const canvasRect = $('#zoomCanvas').getBoundingClientRect();
  if (!bay.width || !bay.height) return;
  const scale = Math.max(bay.width / frame.w, bay.height / frame.h);
  const ox = (bay.width - frame.w * scale) / 2;
  const oy = (bay.height - frame.h * scale) / 2;
  const offX = canvasRect.left - frameEl.left;
  const offY = canvasRect.top - frameEl.top;
  const searched = searchedSpots(key);
  const found = state.found.has(key);
  plan.spots.forEach((spot, i) => {
    const px = frame.box.x + spot.u * frame.box.w;
    const py = frame.box.y + spot.v * frame.box.h;
    let x = offX + ox + (px - frame.x) * scale;
    let y = offY + oy + (py - frame.y) * scale;
    const pad = 16;
    x = Math.min(frameEl.width - pad, Math.max(pad, x));
    y = Math.min(frameEl.height - pad, Math.max(pad, y));
    const btn = document.createElement('button');
    btn.type='button';
    btn.className='search-spot';
    btn.dataset.spot = String(i);
    btn.style.left = `${x}px`; btn.style.top = `${y}px`;
    if (searched.has(i)) btn.dataset.searched = 'true';
    if (i === plan.clueSpot && found) btn.classList.add('is-clue');
    const isClue = i === plan.clueSpot;
    btn.setAttribute('aria-label', `${searched.has(i) ? 'Review' : 'Search'} ${spot.label.toLowerCase()} on ${stationOf(...).name}`);
    btn.innerHTML = `<span class="glint"></span><span class="spot-tag">${spot.label}</span>`;
    btn.addEventListener('click', () => searchSpot(i));
    layer.appendChild(btn);
  });
  requestAnimationFrame(() => requestAnimationFrame(layoutSearchSpots));
}
