}
.search-spot[data-side="top"] .spot-tag{top:auto;bottom:calc(100% - 2px)}
.search-spot[data-side="left"] .spot-tag{left:auto;right:calc(50% + 7px);top:50%;transform:translateY(-50%)}
.search-spot[data-side="right"] .spot-tag{left:calc(50% + 7px);right:auto;top:50%;transform:translateY(-50%)}
.zoom-spots.is-laying-out .spot-tag{transition:none}
.search-spot[data-searched="true"] .glint{
  opacity:.3;border-style:dashed;box-shadow:none;background:rgba(226,194,134,.16);
}
.search-spot[data-searched="true"] .glint::before{animation:none;opacity:.18}
.search-spot[data-searched="true"] .spot-tag{opacity:.55}
.search-spot.is-clue .glint{
  opacity:1;border-style:solid;background:linear-gradient(135deg,#f6d998,#b07a2f);
