}
.search-spot.is-clue .spot-tag{
  color:#f6e6c2;border-color:rgba(243,222,180,.65);background:rgba(30,18,8,.94);
}
.search-spot:active .glint{transform:rotate(45deg) scale(.78)}
.search-spot:focus-visible{outline:2px solid rgba(243,222,180,.9);outline-offset:2px}
.clue-sheet.is-searching .clue-text{color:#3b2f1f;font-style:italic}
#zoomStatus.ok{color:#3d5b2c;font-weight:600}

