function showScreen(name, opts = {}) {
  if (name !== 'zoom' && !opts.keepTransit) cancelZoomTransit();
  state.screen = name;
  app.dataset.scene = name;
  Object.entries(screenMap).forEach(([key, id]) => {
    document.getElementById(id).classList.toggle('is-active', key === name);
