  startCase();
  const missingLabel = [];
  const missingPhrase = [];
  const badPlan = [];
  const clueTexts = {};
  const spotCounts = new Set();
  const labelSeen = new Set();
  for (const loc of LOCATIONS) {
    ensureSceneExtras(loc);
    for (const key of Object.keys(SCENES[loc.scene].stations)) {
      const meta = stationOf(loc, key);
      const type = SCENES[loc.scene].stations[key].t;
      if (!SEARCH_SPOT_LABELS[type]) missingLabel.push([loc.scene, key, type]);
      const set = searchSpotSet(loc, key);
      spotCounts.add(set.labels.length);
      if (set.labels.length < 3 || set.labels.length > 4) badPlan.push([loc.scene, key, 'count', set.labels.length]);
      if (new Set(set.labels).size !== set.labels.length) badPlan.push([loc.scene, key, 'dupe', set.labels]);
      for (const label of set.labels) {
        labelSeen.add(label);
        if (!SPOT_PLACE_PHRASES[label]) missingPhrase.push([loc.scene, key, label]);
        const phrase = spotPhrase(label, meta);
        if (/\{|\}|undefined/.test(phrase)) badPlan.push([loc.scene, key, 'phrase', label, phrase]);
      }
      for (let n = 0; n < 3; n++) {
        const plan = buildSearchPlan(loc, key);
        if (plan.spots.some((s, i) => i !== plan.clueSpot && (!s.text || /\{|\}|undefined/.test(s.text)))) {
          badPlan.push([loc.scene, key, 'flavor', plan.spots.map((s) => s.text)]);
        }
        const hidden = plan.spots[plan.clueSpot];
        const clueText = `Place: ${spotPhrase(hidden.label, meta)}`;
        (clueTexts[type] = clueTexts[type] || new Set()).add(plan.clueSpot + ':' + hidden.label);
      }
    }
  }
  // generate 200 cases and inspect every clue text for unresolved tokens
  const badClue = [];
  const typesSeen = new Set();
  for (let i = 0; i < 200; i++) {
    startCase();
    const c = state.caseData;
    for (const key of c.objects.map((o) => o.key)) {
      const clue = c.clues[key];
      typesSeen.add(clue.type);
      if (/\{|\}|undefined/.test(clue.text)) badClue.push([c.location.scene, key, clue.type, clue.text]);
      const plan = c.searches[key];
      const hidden = plan.spots[plan.clueSpot];
      if (!clue.text.toLowerCase().includes(spotPhrase(hidden.label, stationOf(c.location, key)).toLowerCase())) {
        badClue.push([c.location.scene, key, clue.type, 'no-place-match', hidden.label, clue.text]);
