import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(400);

const foundGun = await page.evaluate(() => {
  for (let i = 0; i < 80; i++) {
    startCase();
    const c = state.caseData;
    const gunKey = c.objects.map((o) => o.key).find((k) => c.clues[k].type === 'gun');
    if (gunKey) {
      goScene();
      openObject(gunKey);
      return { key: gunKey, loc: c.location.name, count: c.objects.length, plan: getSearchPlan(gunKey) };
    }
  }
  return null;
});
if (!foundGun) throw new Error('no gun case');
await page.waitForTimeout(900);
const before = await page.evaluate(() => ({
  text: document.querySelector('#clueText').textContent,
  gun: document.querySelector('#clueSheet').classList.contains('is-gun'),
  clue: document.querySelector('#clueSheet').classList.contains('is-searching'),
  spots: document.querySelectorAll('.search-spot').length
}));
console.log('gun case', JSON.stringify(foundGun.plan));
console.log('before', JSON.stringify(before));
const clueIndex = foundGun.plan.clueSpot;
const falseIndex = foundGun.plan.spots.map((_, i) => i).find((i) => i !== clueIndex);
await page.click(`.search-spot[data-spot="${falseIndex}"]`);
await page.waitForTimeout(250);
const missed = await page.evaluate(() => ({
  text: document.querySelector('#clueText').textContent,
  status: document.querySelector('#zoomStatus').textContent,
  found: state.found.size
}));
console.log('after false', JSON.stringify(missed));
await page.click(`.search-spot[data-spot="${clueIndex}"]`);
await page.waitForTimeout(500);
const clue = await page.evaluate(() => ({
  text: document.querySelector('#clueText').textContent,
  status: document.querySelector('#zoomStatus').textContent,
  gun: document.querySelector('#clueSheet').classList.contains('is-gun'),
  searching: document.querySelector('#clueSheet').classList.contains('is-searching'),
  found: state.found.size,
  clueBtn: document.querySelector('.search-spot.is-clue')?.dataset.spot
}));
console.log('after clue', JSON.stringify(clue));
await page.click(`.search-spot[data-spot="${falseIndex}"]`);
await page.waitForTimeout(250);
const review = await page.evaluate(() => ({
  text: document.querySelector('#clueText').textContent,
  status: document.querySelector('#zoomStatus').textContent,
  gun: document.querySelector('#clueSheet').classList.contains('is-gun'),
  found: state.found.size
}));
console.log('after review false', JSON.stringify(review));
await page.screenshot({ path: '/tmp/opencode/shots2/review-gun.png' });

// variation across cases
const variation = await page.evaluate(() => {
  const seen = new Set();
  const flavor = new Set();
  const clueSpotByObject = {};
  for (let i = 0; i < 40; i++) {
    startCase();
    const c = state.caseData;
    for (const o of c.objects) {
      const p = c.searches[o.key];
      seen.add(`${o.key}:${c.clues[o.key].type}:${p.clueSpot}`);
      p.spots.forEach((s) => { if (s.text) flavor.add(s.text); });
      (clueSpotByObject[o.key] = clueSpotByObject[o.key] || new Set()).add(p.clueSpot);
      if (p.spots.filter((s) => !s.text).length !== 1) throw new Error('bad plan');
    }
  }
  return {
    uniquePlans: seen.size,
    uniqueFlavor: flavor.size,
    objectsWithMultipleSpots: Object.values(clueSpotByObject).filter((s) => s.size > 1).length,
    totalObjects: Object.keys(clueSpotByObject).length
  };
});
console.log('variation', JSON.stringify(variation));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();
