import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(300);
const out = await page.evaluate(() => {
  let maxFlavor = { len: 0 };
  let maxClue = { len: 0 };
  const flavorByKind = {};
  // all static stations
  for (const loc of LOCATIONS) {
    ensureSceneExtras(loc);
    for (const key of Object.keys(SCENES[loc.scene].stations)) {
      const meta = stationOf(loc, key);
      const kind = meta.kind || 'surface';
      for (let n = 0; n < 15; n++) {
        const p = buildSearchPlan(loc, key);
        p.spots.forEach((s) => {
          if (s.text && s.text.length > maxFlavor.len) maxFlavor = { len: s.text.length, text: s.text, scene: loc.scene, key, kind, label: s.label };
        });
        const hidden = p.spots[p.clueSpot];
        const place = spotPhrase(hidden.label, meta);
        if (place.length > maxClue.len) maxClue = { len: place.length, text: place, scene: loc.scene, key, kind, label: hidden.label };
      }
    }
  }
  // actual clues across cases
  let maxRealClue = { len: 0 };
  for (let i = 0; i < 100; i++) {
    startCase();
    const c = state.caseData;
    c.objects.forEach((o) => {
      const clue = c.clues[o.key];
      if (clue.text.length > maxRealClue.len) maxRealClue = { len: clue.text.length, text: clue.text, scene: c.location.scene, key: o.key, type: clue.type };
    });
  }
  return { maxFlavor, maxClue, maxRealClue };
});
console.log(JSON.stringify(out, null, 1));
await browser.close();
EOF
