cat > /tmp/opencode/audit/longtext.mjs <<'EOF'
import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 320, height: 480 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(300);
for (const [w, h] of [[320, 480], [360, 640], [390, 844]]) {
  await page.setViewportSize({ width: w, height: h });
  const rep = await page.evaluate(async () => {
    startCase();
    const base = state.caseData;
    const text = 'A betting slip found under the washstand puts Sonny Delacroix here at 1:35. That is not the story Sonny Delacroix told, and the rain has already taken the rest.';
    const bad = [];
    let checked = 0;
    for (const loc of LOCATIONS) {
      ensureSceneExtras(loc);
      const keys = Object.keys(SCENES[loc.scene].stations);
      state.caseData = {
        ...base,
        location: loc,
        objects: keys.map((key, i) => ({ key, index: i })),
        clues: Object.fromEntries(keys.map((key) => [key, { object: key, type: 'alibi', text }])),
        searches: {}
      };
      state.found = new Set();
      state.searched = new Map();
      for (const key of keys) {
        state.currentObject = key;
        showScreen('zoom');
        document.getAnimations().forEach((a) => { try { a.finish(); } catch {} });
        await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
        checked++;
        const sheet = document.querySelector('.clue-sheet').getBoundingClientRect();
        const actions = document.querySelector('.footer-actions').getBoundingClientRect();
        const art = document.querySelector('#zoomArt').getBoundingClientRect();
        const bay = document.querySelector('#zoomCanvas').getBoundingClientRect();
        const layer = document.querySelector('#zoomSpots').getBoundingClientRect();
        const tags = [...document.querySelectorAll('.spot-tag')].map((t) => t.getBoundingClientRect());
        const pageOver = document.scrollingElement.scrollHeight - innerHeight;
        if (sheet.bottom > actions.top + 1 || actions.bottom > innerHeight + 1 || pageOver > 0 || bay.height < 70 || art.height < 90) {
          bad.push([loc.scene, key, {
            gap: +(actions.top - sheet.bottom).toFixed(1),
            actionsBottom: +actions.bottom.toFixed(1), inner: innerHeight,
            pageOver, artH: +art.height.toFixed(1), bayH: +bay.height.toFixed(1), textH: +sheet.height.toFixed(1)
          }]);
        }
        if (tags.some((t) => t.left < layer.left - 1 || t.right > layer.right + 1 || t.top < layer.top - 1 || t.bottom > layer.bottom + 1)) {
          bad.push([loc.scene, key, 'tag-out']);
        }
      }
    }
    state.caseData = base;
    return { checked, badCount: bad.length, bad: bad.slice(0, 10) };
  });
  console.log(`${w}x${h}`, JSON.stringify(rep));
}
console.log('ERRORS', JSON.stringify(errors));
await browser.close();
EOF
