import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(300);
const rows = await page.evaluate(() => {
  const seen = new Set();
  const out = [];
  for (let i = 0; i < 300 && out.length < 80; i++) {
    startCase();
    const c = state.caseData;
    c.objects.forEach((o) => {
      const meta = stationOf(c.location, o.key);
      const p = c.searches[o.key];
      const spot = p.spots[p.clueSpot];
      const key = `${meta.kind}:${spot.label}:${c.clues[o.key].type}`;
      if (seen.has(key)) return;
      seen.add(key);
      out.push({ kind: meta.kind, label: spot.label, type: c.clues[o.key].type, text: c.clues[o.key].text });
    });
  }
  return out;
});
rows.sort((a, b) => a.type.localeCompare(b.type) || a.kind.localeCompare(b.kind));
rows.forEach((r) => console.log(`${r.type.padEnd(7)} ${r.kind.padEnd(9)} ${r.label.padEnd(14)} ${r.text}`));
await browser.close();
