const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 320, height: 480 } });
await page.emulateMedia({ reducedMotion: 'reduce' });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(300);

for (const [w, h] of [[320, 480], [390, 844]]) {
  await page.setViewportSize({ width: w, height: h });
  const rep = await page.evaluate(async () => {
    const bad = [];
    let views = 0;
    let clicks = 0;
    let blocked = 0;
    for (let c = 0; c < 30; c++) {
      startCase();
      const data = state.caseData;
      goScene();
      for (const o of data.objects) {
        state.currentObject = o.key;
        showScreen('zoom');
        await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
        const plan = getSearchPlan(o.key);
        const order = plan.spots.map((_, i) => i).sort(() => Math.random() - 0.5);
        for (const i of order) {
          // verify the pip can actually be hit at its center
          const btn = document.querySelector(`.search-spot[data-spot="${i}"]`);
          const r = btn.getBoundingClientRect();
          const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2)?.closest('.search-spot');
          if (hit !== btn) blocked++;
          searchSpot(i);
          clicks++;
          await new Promise((r2) => requestAnimationFrame(() => requestAnimationFrame(r2)));
          views++;
          const sheet = document.querySelector('.clue-sheet').getBoundingClientRect();
          const actions = document.querySelector('.footer-actions').getBoundingClientRect();
          const art = document.querySelector('#zoomArt').getBoundingClientRect();
          const bay = document.querySelector('#zoomCanvas').getBoundingClientRect();
          const layer = document.querySelector('#zoomSpots').getBoundingClientRect();
          const tags = [...document.querySelectorAll('.spot-tag')].map((t) => t.getBoundingClientRect());
          const pageOver = document.scrollingElement.scrollHeight - innerHeight;
          if (sheet.bottom > actions.top + 1 || actions.bottom > innerHeight + 1 || pageOver > 0 || bay.height < 70 || art.height < 90) {
            bad.push(['layout', data.location.scene, o.key, i, {
              gap: +(actions.top - sheet.bottom).toFixed(1), actionsBottom: +actions.bottom.toFixed(1),
              inner: innerHeight, pageOver, artH: +art.height.toFixed(1), bayH: +bay.height.toFixed(1)
            }]);
          }
          if (tags.some((t) => t.left < layer.left - 1 || t.right > layer.right + 1 || t.top < layer.top - 1 || t.bottom > layer.bottom + 1)) {
            bad.push(['tag-out', data.location.scene, o.key, i]);
          }
          if (document.querySelectorAll('.search-spot').length !== plan.spots.length) bad.push(['spots-gone', o.key, i]);
        }
      }
    }
    return { views, clicks, blocked, badCount: bad.length, bad: bad.slice(0, 10) };
  });
  console.log(`${w}x${h}`, JSON.stringify(rep));
}
console.log('ERRORS', JSON.stringify(errors));
await browser.close();
