import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 320, height: 480 }, reducedMotion: 'reduce' });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(300);
const start = await page.evaluate(() => {
  for (let i = 0; i < 100; i++) {
    startCase();
    if (state.caseData.objects.length >= 6) break;
  }
  const c = state.caseData;
  goScene();
  return { loc: c.location.name, count: c.objects.length, killer: c.suspects[c.killerIndex].name, gun: gunObjectKey() };
});
for (let i = 0; i < start.count; i++) {
  const key = await page.evaluate((i) => state.caseData.objects[i].key, i);
  await page.evaluate((key) => { openObject(key); }, key);
  const plan = await page.evaluate(() => ({ clue: getSearchPlan(state.currentObject).clueSpot, count: getSearchPlan(state.currentObject).spots.length }));
  for (let s = 0; s < plan.count; s++) await page.evaluate((idx) => searchSpot(idx), s);
  const stateNow = await page.evaluate((key) => ({ found: state.found.has(key), text: document.querySelector('#clueText').textContent }), key);
  if (!stateNow.found) errors.push('failed to log ' + key);
  await page.evaluate(() => goScene());
}
const boardState = await page.evaluate(() => {
  goBoard();
  return { found: state.found.size, count: state.caseData.objects.length, board: document.querySelector('#boardClueCount').textContent, unlocked: document.querySelectorAll('.clue-row:not(.locked)').length, gun: hasSmokingGun() };
});
console.log('start', JSON.stringify(start));
console.log('board', JSON.stringify(boardState));
const accused = await page.evaluate(() => {
  goBoard();
  showScreen('accuse');
  selectSuspect(state.caseData.killerIndex);
  return { screen: state.screen, can: !document.querySelector('#btnMakeAccusation').disabled };
});
console.log('accuse', JSON.stringify(accused));
await page.click('#btnMakeAccusation');
await page.waitForTimeout(150);
await page.click('#btnDoAccuse');
await page.waitForTimeout(900);
const end = await page.evaluate(() => ({ screen: state.screen, stamp: document.querySelector('#endStamp').textContent, copy: document.querySelector('#endCopy').textContent, caseNo: document.querySelector('#endCaseNo').textContent }));
console.log('end', JSON.stringify(end));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();
EOF
