  const out = { checks: [] };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const M = window.__midnight;
  const state = M.state;
  const c = state.caseData;
  const key = c.objects[0].key;
  M.showScreen('scene');
  M.openObject(key);
  await sleep(700);

  const plan = M.getSearchPlan(key);
  out.spots = plan.spots.length;
  out.labels = plan.spots.map((s) => s.label);
  out.clueSpot = plan.clueSpot;

  // Search every non-clue spot first. Nothing may be logged.
  for (let i = 0; i < plan.spots.length; i++) {
    if (i === plan.clueSpot) continue;
    M.searchSpot(i);
    await sleep(30);
  }
  out.foundBefore = state.found.size;
  out.tokenBefore = document.querySelectorAll('#zoomFinds .clue-find').length;

