  out.sheetRevealed = document.querySelector('#clueSheet').classList.contains('is-revealed');
  out.sheetText = document.querySelector('#clueText').textContent;
  out.tokenTag = token?.dataset.tag;

  // Click the physical token: now it logs.
  token?.click();
