  out.foundAfterTake = state.found.size;
  out.sheetLogged = document.querySelector('#clueText').textContent === c.clues[key].text;
  out.statusAfterTake = document.querySelector('#zoomStatus').textContent;
  out.tokenGone = !document.querySelector('#zoomFinds .clue-find');

  // Leave and re-enter: the logged clue survives, no stale token.
  M.goScene(); await sleep(600);
  M.openObject(key); await sleep(700);
  out.reopenToken = document.querySelectorAll('#zoomFinds .clue-find').length;
  out.reopenLogged = document.querySelector('#zoomStatus').textContent.includes('LOGGED');
  out.reopenSpots = document.querySelectorAll('#zoomSpots .search-spot').length;

  // Layout sanity inside the bay.
  const bay = document.querySelector('#zoomCanvas').getBoundingClientRect();
  const spots = [...document.querySelectorAll('#zoomSpots .search-spot')].map((b) => b.getBoundingClientRect());
  out.spotsInside = spots.every((b) => b.left >= bay.left - 1 && b.right <= bay.right + 1 && b.top >= bay.top - 1 && b.bottom <= bay.bottom + 1);
  out.overflowX = document.documentElement.scrollWidth - window.innerWidth;
  out.overflowY = document.documentElement.scrollHeight - window.innerHeight;

  // Variation: same object across many generated cases should get
  // different hiding places and different room-search plans.
  const seen = new Set();
  const spotCounts = new Set();
  for (let n = 0; n < 40; n++) {
    state.caseData = M.makeCase();
    const plan2 = M.getSearchPlan(key);
    if (!plan2) continue;
    seen.add(plan2.clueSpot + ':' + plan2.spots.map((s) => s.label).join('|'));
    spotCounts.add(plan2.spots.length);
  }
  out.planVariants = seen.size;
  out.spotCounts = [...spotCounts];
  return out;
});

