const browser = await puppeteer.launch({
  executablePath: '/usr/bin/chromium',
  headless: 'new',
  args: ['--no-sandbox', '--disable-dev-shm-usage', '--mute-audio']
});
const page = await browser.newPage();
await page.setViewport({ width: 390, height: 844, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await page.goto('http://127.0.0.1:8123/index.html', { waitUntil: 'load' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await sleep(400);
await page.click('#phoneZone'); await sleep(100);
await page.click('#btnCallNext'); await sleep(100);
await page.click('#btnCallNext'); await sleep(500);
const info = await page.evaluate(async () => {
  const M = window.__midnight, state = M.state;
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const c = M.makeCase();
  state.caseData = c; state.found = new Set(); state.searched = new Map();
  M.showScreen('scene');
  M.openObject(c.objects[0].key);
  await sleep(800);
  const plan = M.getSearchPlan(c.objects[0].key);
  M.searchSpot(plan.clueSpot);
  await sleep(500);
  const station = document.querySelector(`#zoomCanvas .closeup-svg [data-station="${c.objects[0].key}"]`);
  return {
    key: c.objects[0].key,
    clueType: c.clues[c.objects[0].key].type,
    animation: station ? getComputedStyle(station).animationName : null,
    tokenRect: document.querySelector('.clue-find')?.getBoundingClientRect().toJSON(),
    bayRect: document.querySelector('#zoomCanvas').getBoundingClientRect().toJSON()
  };
});
console.log(info);
await page.screenshot({ path: '/tmp/opencode/audit/revealed.png' });
