import puppeteer from 'puppeteer-core';

const browser = await puppeteer.launch({
  executablePath: '/usr/bin/chromium',
  headless: 'new',
  args: ['--no-sandbox', '--disable-dev-shm-usage', '--mute-audio']
});
const page = await browser.newPage();
await page.setViewport({ width: 390, height: 844, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto('http://127.0.0.1:8123/index.html', { waitUntil: 'load' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await sleep(400);
await page.tap('#phoneZone'); await sleep(100);
await page.tap('#btnCallNext'); await sleep(100);
await page.tap('#btnCallNext'); await sleep(600);

const key = await page.evaluate(() => {
  const M = window.__midnight;
  M.goScene();
  const k = M.state.caseData.objects[0].key;
  M.openObject(k);
  return k;
});
await sleep(900);

const info = await page.evaluate((k) => {
  const M = window.__midnight;
  const plan = M.getSearchPlan(k);
  return { key: k, clueSpot: plan.clueSpot, count: plan.spots.length };
}, key);

// Tap actual pips with the mouse/touch, one at a time. Stop when revealed.
let revealed = false;
for (let i = 0; i < info.count; i++) {
  const btn = await page.$(`#zoomSpots .search-spot[data-spot="${i}"]`);
  const box = await btn.boundingBox();
  if (!box) { console.log('no box for', i); continue; }
  await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2);
  await sleep(220);
  revealed = await page.evaluate((k) => window.__midnight.getSearchPlan(k).revealed, key);
  console.log(`pip ${i} tapped, searched=`, await page.evaluate((i) => document.querySelector(`.search-spot[data-spot="${i}"]`).dataset.searched, i), 'revealed=', revealed);
  if (revealed) break;
}
const after = await page.evaluate((k) => ({
  found: window.__midnight.state.found.size,
  status: document.querySelector('#zoomStatus').textContent,
  token: !!document.querySelector('.clue-find'),
  clueType: window.__midnight.state.caseData.clues[k].type
}), key);
console.log(info, after);
if (after.token) {
  await page.tap('.clue-find');
  await sleep(500);
  console.log('after taking:', await page.evaluate((k) => ({
    found: window.__midnight.state.found.size,
    has: window.__midnight.state.found.has(k),
    status: document.querySelector('#zoomStatus').textContent,
    sheet: document.querySelector('#clueText').textContent
  }), key));
}
console.log('errors', errors);
await browser.close();

