/* ================= SOUND (OPTIONAL, USER ENABLED) ================= */
const Sfx = {
  ctx: null, master: null, enabled: false, rainNode: null, rainGain: null, ringTimer: null,
  init() {
    if (this.ctx) return true;
    const AC = window.AudioContext || window.webkitAudioContext;
  if (name === 'scene') {
