import puppeteer from 'puppeteer-core';

const browser = await puppeteer.launch({
  executablePath: '/usr/bin/chromium',
  headless: 'new',
  args: ['--no-sandbox', '--disable-dev-shm-usage', '--mute-audio']
});
const page = await browser.newPage();
await page.setViewport({ width: 390, height: 844, isMobile: true, hasTouch: true });
await page.goto('http://127.0.0.1:8123/index.html', { waitUntil: 'load' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await sleep(350);
await page.tap('#phoneZone'); await sleep(100);
await page.tap('#btnCallNext'); await sleep(100);
await page.tap('#btnCallNext'); await sleep(500);
const out = await page.evaluate(async () => {
  const M = window.__midnight, state = M.state;
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const c = M.makeCase();
  state.caseData = c; state.found = new Set(); state.searched = new Map();
  M.showScreen('scene');
  const key = c.objects[0].key;
  M.openObject(key); await sleep(800);
  const plan = M.getSearchPlan(key);
  M.searchSpot(plan.clueSpot); await sleep(300);
  const before = { found: state.found.size, token: !!document.querySelector('.clue-find') };
  // Leave without taking, then come back.
  M.goScene(); await sleep(900);
  const foundOnBoard = state.found.size;
  M.openObject(key); await sleep(900);
  const after = {
    found: state.found.size,
    revealed: M.getSearchPlan(key).revealed,
    token: !!document.querySelector('.clue-find'),
    status: document.querySelector('#zoomStatus').textContent,
    hasFind: !!document.querySelector('.search-spot.has-find'),
    sheetText: document.querySelector('#clueText').textContent
  };
  // Clicking the already-revealed spot should take it, not merely re-search.
  const pip = document.querySelector(`.search-spot[data-spot="${plan.clueSpot}"]`);
  pip.click(); await sleep(300);
  const taken = { found: state.found.size, has: state.found.has(key), token: !!document.querySelector('.clue-find') };
  return { key, before, foundOnBoard, after, taken };
});
console.log(JSON.stringify(out, null, 2));
await browser.close();

