.sus-content{flex:1;min-width:0}
.sus-top{display:flex;align-items:baseline;gap:7px;min-width:0}
.sus-name{font-family:var(--serif);font-size:clamp(12.5px,1.9vh,15.5px);font-weight:900;line-height:1;color:var(--paper);letter-spacing:-.01em;white-space:nowrap}
