.sus-line b{font-size:5.8px;letter-spacing:.13em;color:var(--paper-faint);font-weight:500;flex:0 0 auto;padding-top:1.7px}
.sus-line span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-family:var(--type)}
.board-notes{
