import puppeteer from 'puppeteer-core';
const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--mute-audio'] });
for (const [w, h] of [[320,568],[360,640],[390,844]]) {
  const page = await browser.newPage();
  await page.setViewport({ width: w, height: h, isMobile: true, hasTouch: true });
  await page.goto('http://127.0.0.1:8123/index.html', { waitUntil: 'load' });
  await new Promise((r) => setTimeout(r, 300));
  const out = await page.evaluate(async () => {
    const M = window.__midnight, state = M.state;
    let c = M.makeCase(), guard = 0;
    while (c.objects.length < 8 && guard++ < 300) c = M.makeCase();
    state.caseData = c; state.found = new Set(); c.objects.forEach((o) => state.found.add(o.key));
    M.showScreen('board');
    await new Promise((r) => setTimeout(r, 400));
    const rect = (sel) => { const e = document.querySelector(sel); const r = e.getBoundingClientRect(); return [Math.round(r.top), Math.round(r.bottom), Math.round(r.height)]; };
    return {
      objects: c.objects.length,
      head: rect('.suspects-head'),
      list: rect('.suspect-list'),
      rows: [...document.querySelectorAll('.suspect-row')].map((e) => { const r = e.getBoundingClientRect(); return [Math.round(r.top), Math.round(r.bottom), Math.round(r.height)]; }),
      suspectsBottom: Math.round(document.querySelector('.suspect-list').getBoundingClientRect().bottom),
      actionsTop: rect('.board-actions')[0],
      notesDisplay: getComputedStyle(document.querySelector('.board-notes')).display,
      susLineDisplay: getComputedStyle(document.querySelector('.sus-line')).display
    };
  });
  console.log(w + 'x' + h, JSON.stringify(out));
  if (w === 320) await page.screenshot({ path: '/tmp/opencode/audit/board-8-320b.png' });
  await page.close();
}
await browser.close();

