import puppeteer from 'puppeteer-core';
const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--mute-audio'] });
const page = await browser.newPage();
await page.setViewport({ width: 390, height: 844, isMobile: true, hasTouch: true });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto('http://127.0.0.1:8123/index.html', { waitUntil: 'load' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await sleep(300);
await page.tap('#phoneZone'); await sleep(80); await page.tap('#btnCallNext'); await sleep(80); await page.tap('#btnCallNext'); await sleep(400);
const out = await page.evaluate(async () => {
  const M = window.__midnight, state = M.state;
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const c = M.makeCase();
  state.caseData = c; state.found = new Set(); state.searched = new Map();
  M.showScreen('scene');
  // Work every object through the two-stage discovery.
  for (const o of c.objects) {
    M.openObject(o.key); await sleep(80);
    const plan = M.getSearchPlan(o.key);
    for (let i = 0; i < plan.spots.length; i++) {
      M.searchSpot(i); await sleep(5);
      if (M.getSearchPlan(o.key).revealed) break;
    }
    if (!M.getSearchPlan(o.key).revealed) throw new Error('never revealed ' + o.key);
    M.collectClue(o.key); await sleep(5);
    M.goScene(); await sleep(20);
  }
  const allFound = state.found.size === c.objects.length;
  const gunKey = c.objects.find((o) => c.clues[o.key].type === 'gun').key;
  const gunFound = state.found.has(gunKey);
  M.showScreen('board'); await sleep(300);
  const boardCount = document.querySelector('#boardClueCount').textContent;
  M.showScreen('accuse'); await sleep(300);
  M.accuseIndex(c.killerIndex); await sleep(600);
  const end = {
    screen: state.screen,
    win: document.querySelector('#screen-end').classList.contains('is-win'),
    headline: document.querySelector('#endHeadline').textContent,
    nail: document.querySelector('#endNail').textContent.slice(0, 80)
  };
  const rect = (s) => { const r = document.querySelector(s).getBoundingClientRect(); return [Math.round(r.top), Math.round(r.bottom)]; };
  return { objects: c.objects.length, allFound, gunFound, boardCount, end, endCard: rect('.end-card'), inner: innerHeight, docScroll: document.documentElement.scrollHeight };
});
console.log(JSON.stringify(out, null, 2));
console.log('errors', errors);
await page.screenshot({ path: '/tmp/opencode/audit/end.png' });
await browser.close();

