import puppeteer from 'puppeteer-core';
const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--mute-audio'] });
const page = await browser.newPage();
await page.setViewport({ width: 390, height: 844, isMobile: false, hasTouch: false });
await page.goto('http://127.0.0.1:8123/index.html', { waitUntil: 'load' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await sleep(300);
await page.click('#phoneZone'); await sleep(80); await page.click('#btnCallNext'); await sleep(80); await page.click('#btnCallNext'); await sleep(400);
const key = await page.evaluate(async () => {
  const M = window.__midnight, state = M.state;
  const c = M.makeCase(); state.caseData = c; state.found = new Set(); state.searched = new Map();
  state.currentObject = c.objects[0].key; M.showScreen('zoom');
  return c.objects[0].key;
});
await sleep(700);
const spot = await page.evaluate((k) => window.__midnight.getSearchPlan(k).clueSpot, key);
await page.focus(`.search-spot[data-spot="${spot}"]`);
await page.keyboard.press('Enter');
await sleep(300);
const mid = await page.evaluate(() => ({
  found: window.__midnight.state.found.size,
  revealed: window.__midnight.getSearchPlan(window.__midnight.state.currentObject).revealed,
  active: document.activeElement.className,
  token: !!document.querySelector('.clue-find')
}));
await page.keyboard.press('Enter');
await sleep(300);
const end = await page.evaluate((k) => ({
  found: window.__midnight.state.found.size,
  has: window.__midnight.state.found.has(k),
  active: document.activeElement.className
}), key);
console.log({ key, spot, mid, end });
await browser.close();

